package com.example

/**
 * Domain 7: Colonial Sri Lanka, Early British Rule & Liberation Rebellions
 * (පෘතුගීසි, ලන්දේසි, මුල් බ්‍රිතාන්‍ය පාලනය, කෝල්බෲක් ප්‍රතිසංස්කරණ, 1818 හා 1848 නිදහස් අරගල)
 * Clean Sinhala questions aligned with syllabus. NO lesson title prefixes.
 */
object HistoryLiveExamColonialSriLankaBank {
  private val T = HistoryTopicDomain.COLONIAL_SRI_LANKA

  private fun q(
    topic: HistoryTopicDomain,
    stem: String,
    correct: String,
    distractor1: String,
    distractor2: String,
    distractor3: String,
    explanation: String
  ): HistoryCuratedQuestion {
    return HistoryCuratedQuestion(
      stem = stem,
      options = listOf(correct, distractor1, distractor2, distractor3),
      correctIndex = 0,
      explanation = explanation,
      topic = topic
    )
  }

  fun colonialSriLankaAndRebellionsQuestions(): List<HistoryCuratedQuestion> = listOf(
    q(T, "ශ්‍රී ලංකාවට පැමිණි ප්‍රථම යුරෝපීය ජාතිය වූයේ කවුරුන්ද?", "පෘතුගීසීන්", "ලන්දේසීන්", "ඉංග්‍රීසීන්", "ප්‍රංශ ජාතිකයන්", "ක්‍රි.ව. 1505 දී ලොරෙන්සෝ ද අල්මේදා ප්‍රමුඛ පෘතුගීසි නාවික පිරිස කුණාටුවකට හසුව ගාලු වරායට ගසාගෙන විත් පසුව කොළඹට පැමිණියහ."),
    q(T, "ක්‍රි.ව. 1505 දී ලංකාවට පැමිණි පෘතුගීසි නාවික කණ්ඩායමේ නායකයා වූයේ කවුද?", "ලොරෙන්සෝ ද අල්මේදා (Lourenco de Almeida)", "ලෝපෝ සෝරස් ද ඇල්බර්ගාරියා", "කොන්ස්තන්තීනු ද සා", "පිලිප් ද ඔලිවේරා", "ඉන්දියාවේ පෘතුගීසි ප්‍රතිරාජ ෆ්‍රැන්සිස්කෝ ද අල්මේදාගේ පුත් ලොරෙන්සෝ ද අල්මේදා ලංකාවට පැමිණි ප්‍රථම පෘතුගීසි නායකයා විය."),
    q(T, "පෘතුගීසීන් ලංකාවට පැමිණෙන විට කෝට්ටේ රාජධානියේ පාලකයා ලෙස කටයුතු කළේ කවුද?", "අටවන වීර පරාක්‍රමබාහු රජු", "හයවන පරාක්‍රමබාහු රජු", "භුවනෙකබාහු රජු", "මායාදුන්නේ රජු", "පෘතුගීසීන් සමඟ මුලින්ම සාකච්ඡා කර කුරුඳු ලබාදීමට එකඟතාව පළ කළේ අටවන වීර පරාක්‍රමබාහු රජුය."),
    q(T, "පෘතුගීසීන්ගේ පැමිණීම පිළිබඳව 'අපේ කොළොම්තොටට යකඩ ඇඳුම් ඇඳගත්, පාන් කන ලේ බොන ජාතියක් ඇවිත්' යනුවෙන් සඳහන් වන්නේ කුමන ඓතිහාසික මූලාශ්‍රයේද?", "රාජාවලිය", "මහාවංශය", "චූලවංශය", "පූජාවලිය", "රාජාවලියේ කෝට්ටේ රජුට ඔත්තුකරුවන් විසින් පෘතුගීසීන්ගේ ස්වරූපය විස්තර කළ අයුරු මෙසේ නිරූපණය කර ඇත."),
    q(T, "පෘතුගීසීන්ට මුල්වරට කොළඹ බලකොටුවක් සහ වෙළඳ මධ්‍යස්ථානයක් ඉදිකිරීමට අවසර දුන්නේ කවුද?", "ධර්ම පරාක්‍රමබාහු රජු", "හයවන පරාක්‍රමබාහු රජු", "භුවනෙකබාහු රජු", "මායාදුන්නේ රජු", "1518 දී ලෝපෝ සෝරස් ද ඇල්බර්ගාරියා පැමිණ කොළඹ ශාන්ත ලෝරන්ස් කොටුව ඉදි කිරීමට ගිවිස ගන්නා ලදී."),
    q(T, "ක්‍රි.ව. 1521 දී කෝට්ටේ රාජධානිය තුනට බෙදී යාමට හේතු වූ ඓතිහාසික සිදුවීම කුමක්ද?", "විජයබා කොල්ලය", "දොන් ජුවන්ගේ තෑගි ඔප්පුව", "දාන්තේ සටන", "මුල්ලේරියා සටන", "විජයබාහු රජුගේ පුතුන් තිදෙනා (භුවනෙකබාහු, පරරාජසිංහ, මායාදුන්නේ) තම පියා මරා රාජධානිය කෝට්ටේ, රයිගම හා සීතාවක ලෙස බෙදා ගත්හ."),
    q(T, "කෝට්ටේ හත්වන භුවනෙකබාහු රජු තම මුණුබුරා වූ ධර්මපාල කුමරුගේ රන් පිළිරුවක් පෘතුගාලයට යවා කළ ඉල්ලීම කුමක්ද?", "තමාගෙන් පසු ධර්මපාල කුමරු කෝට්ටේ රජු ලෙස ඔටුනු පැළඳවීම", "තම රාජධානිය පෘතුගාලයට පැවරීම", "යුද හමුදාවක් එවන ලෙස", "කතෝලික ධර්මය වැළඳගැනීමට", "තුන්වන ජෝන් පෘතුගාල රජු විසින් ලිස්බන් නුවරදී ධර්මපාල කුමරුගේ රන් පිළිරුව ඔටුනු පළඳවා උරුමය පිළිගන්නා ලදී."),
    q(T, "කතෝලික ධර්මය වැළඳගත් ලංකාවේ ප්‍රථම රජු බවට පත්වෙමින් 'දොන් ජුවන්' යන නාමය ගත්තේ කවුද?", "ධර්මපාල රජු", "හත්වන භුවනෙකබාහු රජු", "මායාදුන්නේ රජු", "දොන් පිලිප්", "1557 දී ධර්මපාල රජු දොන් ජුවන් ධර්මපාල නමින් බෞතීස්ම ලැබීමත් සමග කෝට්ටේ බෞද්ධ ජනතාව සීතාවකට පක්ෂපාතී වූහ."),
    q(T, "ක්‍රි.ව. 1580 දී දොන් ජුවන් ධර්මපාල රජු විසින් අත්සන් තබන ලද ඓතිහාසික ලේඛනය කුමක්ද?", "තෑගි ඔප්පුව (Donation Deed)", "සාම ගිවිසුම", "කුරුඳු ගිවිසුම", "ආගමික ප්‍රකාශනය", "තමාට දරුවන් නොමැති බැවින් තම මරණයෙන් පසු කෝට්ටේ රාජධානිය පෘතුගාල රජුට හිමිවන පරිදි තෑගි ඔප්පුවකින් පවරන ලදී."),
    q(T, "දොන් ජුවන් ධර්මපාල රජුගේ මරණයෙන් පසු 1597 දී පෘතුගීසීන් සිංහල ප්‍රධානීන් රැස්කර පවත්වන ලද සම්මේලනය කුමක්ද?", "මල්වාන සම්මුතිය (Convention of Malwana)", "කොළඹ සම්මුතිය", "කඳවුරු සම්මුතිය", "මහනුවර ගිවිසුම", "පෘතුගාලයේ පළමුවන පිලිප් රජු ලංකාවේ රජු ලෙස පිළිගන්නා අතර පැරණි සිංහල සිරිත් විරිත් ආරක්ෂා කරන බවට ජෙරනිමෝ ද අසවේදු පොරොන්දු විය."),
    q(T, "පෘතුගීසි පාලනය යටතේ මෙරට ඉහළම පරිපාලන හා හමුදා නිලධාරියා හැඳින්වූයේ කුමන නමින්ද?", "කැප්ටන් ජනරාල් (Captain General)", "ආණ්ඩුකාරවරයා", "විදෝර් ද ෆසෙන්දා", "ඔයිදෝර්", "කොළඹ මූලස්ථානය කරගෙන පෘතුගීසි ලංකාවේ සමස්ත පාලනය කැප්ටන් ජනරාල්වරයා යටතේ පැවතිණි."),
    q(T, "පෘතුගීසි පාලන සමයේ මුදල් හා ආදායම් පාලනය භාරව සිටි උසස් නිලධාරියා කවුද?", "විදෝර් ද ෆසෙන්දා (Vedor da Fazenda)", "ඔයිදෝර්", "කැප්ටන් ජනරාල්", "කනක්කපුල්ලේ", "රාජ්‍ය භාණ්ඩාගාරය, බදු එකතු කිරීම සහ කුරුඳු ආදායම් පාලනය කිරීම විදෝර් ද ෆසෙන්දාගේ වගකීම විය."),
    q(T, "පෘතුගීසීන් විසින් මෙරට ගම්බිම්, ඒවායේ ආදායම් සහ සේවා වාර්තා කිරීම සඳහා සකස් කළ ලේඛන හඳුන්වන්නේ කුමක් ලෙසද?", "තෝම්බු (Tombos)", "ලේකම් මිටි", "සන්නස්", "කඩඉම් පොත්", "ඉඩම් තෝම්බු (Land Register) මගින් බදු අයකර ගැනීම සහ රදළයන්ට ගම් බෙදා දීම විධිමත් කෙරිණි."),
    q(T, "පෘතුගීසි හමුදාවේ කුලී හේවායන් ලෙස සේවය කළ දේශීය සිංහල සෙබළුන් හැඳින්වූයේ කුමන නමින්ද?", "ලස්කිරිඤ්ඤ හමුදාව (Lascorins)", "මුහන්දිරම්වරු", "ආරච්චිවරු", "අතපත්තු හමුදාව", "පෘතුගීසි හමුදාවේ බහුතරය වූයේ දේශීය ලස්කිරිඤ්ඤ භටයන් වූ අතර තීරණාත්මක සටන්වලදී මොවුන් ස්වදේශික රජුන් වෙත පක්ෂපාතී විය."),
    q(T, "පෘතුගීසීන් විසින් සිංහල භාෂාවට දායාද කරන ලද වචන සමූහයක් නොවන්නේ කුමක්ද?", "කුස්සිය, කලිසම, සපත්තු, මේසය, කෝප්පය", "අල්මාරිය, ජනේලය, පීරිසිය, විනාකිරි", "බෝතලය, බයිලා, සාය, කාමරය", "කඩදාසි, පෑන, පොත, ගුරුවරයා", "කඩදාසි, පෑන, පොත යන වචන පෘතුගීසි සම්භවයක් ඇති ඒවා නොවේ; අනෙක් සියල්ල පෘතුගීසි වචනයි."),
    q(T, "ක්‍රි.ව. 1602 දී මහනුවර පළමුවන විමලධර්මසූරිය රජු හමුවීමට පැමිණි ප්‍රථම ලන්දේසි නාවිකයා කවුද?", "ජොරිස් වැන් ස්පිල්බර්ගන් (Joris van Spilbergen)", "සිබෝල්ට් ද වර්ට්", "ගිරාඩ් හල්ෆ්ට්", "විලෙම් ජේකබ්ස්", "නෙදර්ලන්තයේ සිට පැමිණි ස්පිල්බර්ගන් රජු සමග මිත්‍ර සබඳතා ගොඩනගා ගනිමින් පෘතුගීසීන්ට එරෙහිව සහයෝගය පතා සාකච්ඡා කළේය."),
    q(T, "ක්‍රි.ව. 1603 දී මහනුවර රජු හමුවීමට පැමිණ මඩකලපුවේදී අශෝභන ලෙස හැසිරීම නිසා ඝාතනයට ලක්වූ ලන්දේසි උප අද්මිරාල්වරයා කවුද?", "සිබෝල්ට් ද වර්ට් (Sebald de Weert)", "ස්පිල්බර්ගන්", "වැන් ගෝන්ස්", "වැන් ඩර් මෙයිඩන්", "මත්පැන් පානය කර රජුට සහ රැජිනට අපහාස වන අයුරින් කතා කිරීම නිසා පළමුවන විමලධර්මසූරිය රජුගේ නියමයෙන් මොහු මරා දැමිණි."),
    q(T, "ක්‍රි.ව. 1638 මැයි 23 වන දින දෙවන රාජසිංහ රජු සහ ලන්දේසීන් අතර අත්සන් කළ ගිවිසුම කුමක්ද?", "1638 මහනුවර ගිවිසුම (ගිවිසුම් ගාල්ල/මඩකලපුව)", "මල්වාන ගිවිසුම", "උඩරට ගිවිසුම", "හැන්ග්වුරන්කෙත ගිවිසුම", "ඇඩම් වෙස්ටර්වෝල්ඩ් සහ රජු අතර අත්සන් කළ මෙම ගිවිසුම මගින් පෘතුගීසීන් පළවා හැරීමට ලන්දේසි හමුදා ආධාර ලබාගැනීමට එකඟ විය."),
    q(T, "1638 ගිවිසුමේ ලන්දේසි පිටපතට ලන්දේසීන් විසින් කූට ලෙස ඇතුළත් කරන ලද කොන්දේසිය කුමක්ද?", "රජු යුද වියදම් ගෙවන තුරු අල්ලා ගන්නා බලකොටු ලන්දේසි හමුදා භාරයේ තබා ගැනීම", "ලන්දේසීන්ට බදු නොගෙවීම", "බුද්ධාගම විනාශ කිරීම", "රජු සිහසුනෙන් පහ කිරීම", "සිංහල පිටපතේ 'රජු කැමති නම් පමණක්' යැයි තිබූ වගන්තිය ලන්දේසි පිටපතෙන් ඉවත් කර බලකොටු අල්ලාගෙන සිටීමට ලන්දේසීන් පියවර ගත්හ."),
    q(T, "දෙවන රාජසිංහ රජු ලන්දේසීන් මෙරටට ගෙන්වා ගැනීම පිළිබඳව කලකිරීමට පත්ව ප්‍රකාශ කළ සුප්‍රකට කියමන කුමක්ද?", "ඉඟුරු දී මිරිස් ගත්තා වැනි විය", "කිරි කළයට ගොම දැම්මා වැනි විය", "අහසින් වැටුණු මිනිසාට ගොනා ඇන්නා වැනි විය", "කබලෙන් ළිපට වැටුණා වැනි විය", "පෘතුගීසි කරදරයෙන් බේරීමට ලන්දේසීන් ගෙන්වා ගත් නමුත් ලන්දේසීන් ඊටත් වඩා කූට ලෙස වෙරළබඩ අල්ලාගත් බව මින් අදහස් විය."),
    q(T, "ක්‍රි.ව. 1656 දී මාස ගණනාවක් වටලා ප්‍රහාර එල්ල කර පෘතුගීසීන්ගෙන් කොළඹ කොටුව අල්ලා ගත්තේ කවුරුන්ද?", "ලන්දේසීන් සහ දෙවන රාජසිංහ රජුගේ හමුදාව", "ඉංග්‍රීසීන්", "ප්‍රංශ ජාතිකයන්", "සීතාවක හමුදාව", "ජෙනරාල් ගිරාඩ් හල්ෆ්ට් කොළඹ වටලෑමේදී මියගිය අතර පසුව ලන්දේසීන් කොළඹ කොටුව අත්පත් කරගත්තේය."),
    q(T, "පෘතුගීසීන්ගේ අවසාන බලකොටුව වූ යාපනය ලන්දේසීන් විසින් අල්ලා ගනු ලැබුවේ කුමන වර්ෂයේදීද?", "ක්‍රි.ව. 1658 දී", "ක්‍රි.ව. 1640 දී", "ක්‍රි.ව. 1656 දී", "ක්‍රි.ව. 1660 දී", "1658 දී මන්නාරම සහ යාපනය අල්ලා ගැනීමත් සමග ලංකාවේ 153 වසරක පෘතුගීසි බලය මුළුමනින්ම අවසන් විය."),
    q(T, "ලංකාවේ ලන්දේසි පාලනය මෙහෙයවන ලද ලන්දේසි වෙළඳ සමාගම හැඳින්වූ කෙටි නාමය කුමක්ද?", "VOC (Vereenigde Oostindische Compagnie)", "EIC", "BBC", "CFA", "ලන්දේසි පෙරදිග වෙළඳ සමාගම හෙවත් VOC සමාගම මෙරට ලන්දේසි පාලන බලතල ක්‍රියාත්මක කළේය."),
    q(T, "ලන්දේසි පාලන සමයේ මුළු ලන්දේසි බලප්‍රදේශය ප්‍රධාන පරිපාලන කොට්ඨාස 3 කට බෙදා තිබුණේ කෙසේද?", "කොළඹ, ගාල්ල සහ යාපනය කොමාන්ඩරීස් ලෙස", "මාතර, ත්‍රිකුණාමලය, මඩකලපුව", "මහනුවර, සබරගමුව, රුහුණ", "බස්නාහිර, දකුණ, උතුර", "කොළඹ ආණ්ඩුකාරවරයාගේ යටතේද, ගාල්ල සහ යාපනය කොමාන්ඩර්වරුන් (Commandeurs) යටතේද පාලනය විය."),
    q(T, "ලන්දේසීන් විසින් ගැමි ජනතාවගේ පවුල් විස්තර, උපත්, විවාහ සහ ආගම ලියාපදිංචි කිරීම සඳහා පවත්වාගෙන ගිය තෝම්බු විශේෂය කුමක්ද?", "පාසල් තෝම්බු (School Tombos)", "ඉඩම් තෝම්බු", "කුල තෝම්බු", "බදු තෝම්බු", "ලන්දේසි පල්ලිය හා පාසල මගින් පවත්වාගෙන ගිය පාසල් තෝම්බු ක්‍රමය මෙරට ප්‍රථම උප්පැන්න සහ විවාහ ලියාපදිංචි ලේඛනය ලෙස සැලකේ."),
    q(T, "ලන්දේසීන් විසින් ශ්‍රී ලංකාවේ නීති පද්ධතියට දායාද කරන ලද ලොව ප්‍රමුඛතම නීති සම්ප්‍රදාය කුමක්ද?", "රෝම-ලන්දේසි නීතිය (Roman-Dutch Law)", "ඉංග්‍රීසි පොදු නීතිය", "නැපෝලියන් නීතිය", "කැනොන් නීතිය", "වර්තමානයේද ශ්‍රී ලංකාවේ පොදු නීතිය (Common Law) ලෙස රෝම-ලන්දේසි නීතියේ මූලධර්ම ක්‍රියාත්මක වේ."),
    q(T, "යාපනයේ දෙමළ ජනතාවගේ දේශීය නීති පද්ධතිය අධ්‍යයනය කර ලන්දේසීන් විසින් සංග්‍රහ කළ නීතිය කුමක්ද?", "තේසවලාමෙයි නීතිය (Thesawalamai)", "මුස්ලිම් නීතිය", "උඩරට නීතිය", "මනු නීතිය", "ලන්දේසි ආණ්ඩුකාර සිමන්ස්ගේ උපදෙස් මත ක්ලාස් අයිසැක්ස් විසින් තේසවලාමෙයි නීතිය ලිඛිතව සංග්‍රහ කරන ලදී."),
    q(T, "ලන්දේසි පාලන සමයේ ඉඩම් ආරවුල් විසඳීම සඳහා ග්‍රාමීය ප්‍රදේශවල පිහිටුවා තිබූ අධිකරණය කුමක්ද?", "ලෑන්ඩ් රཱඩ් අධිකරණය (Landraad Court)", "සිවිල් උසාවිය", "රාජ්‍ය මන්ත්‍රණ සභාව", "යුද අධිකරණය", "දේශීය මුදලිවරුන්ගේද සහභාගීත්වයෙන් ඉඩම් හා කෘෂිකාර්මික ආරවුල් විසඳීමට ලෑන්ඩ් රཱඩ් අධිකරණය ක්‍රියා කළේය."),
    q(T, "ලන්දේසීන් විසින් භාණ්ඩ ප්‍රවාහනය පහසු කිරීම සඳහා බස්නාහිර වෙරළබඩ ඉදිකළ යටිතල පහසුකම කුමක්ද?", "ඇළ මාර්ග පද්ධතිය (Canals)", "දුම්රිය මාර්ග", "තාර දැමූ මහා මාර්ග", "ගුවන් තොටුපළ", "හැමිල්ටන් ඇළ ඇතුළු කළුතර සිට පුත්තලම දක්වා ඇළ මාර්ග පද්ධතිය ලන්දේසීන්ගේ විශිෂ්ට ඉංජිනේරු නිර්මාණයකි."),
    q(T, "ලන්දේසීන් විසින් ගාලු වරාය සහ නගරය ආරක්ෂා කිරීම සඳහා කළුගලින් ඉදිකළ ලෝක උරුම බලකොටුව කුමක්ද?", "ගාල්ල කොටුව (Galle Fort)", "කොළඹ කොටුව", "මඩකලපු කොටුව", "මන්නාරම් කොටුව", "යුනෙස්කෝ ලෝක උරුමයක් ලෙස නම් කර ඇති ගාලු කොටුව දකුණු ආසියාවේ ඉතිරිව ඇති විශාලතම යුරෝපීය බලකොටුවකි."),
    q(T, "මාතර නිල්වලා ගං ඉවුරේ ලන්දේසීන් විසින් ඉදිකරන ලද තරුවක හැඩය ඇති සුවිශේෂී බලකොටුව කුමක්ද?", "තාරකා කොටුව (Star Fort)", "ගාලු කොටුව", "ෆෙඩ්රික් කොටුව", "හැමන්හිල් කොටුව", "1762 මාතර කැරැල්ලෙන් පසු ආරක්ෂාව තර කිරීම සඳහා වෑන් එක් ආණ්ඩුකාරවරයා විසින් තාරකා කොටුව ඉදිකරන ලදී."),
    q(T, "ක්‍රි.ව. 1766 දී කීර්ති ශ්‍රී රාජසිංහ රජු සහ ලන්දේසි ආණ්ඩුකාර ඉමාන් විලෙම් ෆැල්ක් අතර අත්සන් කළ ගිවිසුම කුමක්ද?", "1766 හඟුරන්කෙත ගිවිසුම", "1638 ගිවිසුම", "මල්වාන ගිවිසුම", "උඩරට ගිවිසුම", "මෙම ගිවිසුම මගින් උඩරට රාජධානිය වටා වූ මුළු වෙරළබඩ තීරයම (ගව්වක පළලින් යුත්) ලන්දේසීන්ට පවරා දීමට රජුට සිදුවිය."),
    q(T, "1766 ගිවිසුම නිසා උඩරට රාජධානියට අත්වූ දරුණුතම අවාසිය කුමක්ද?", "විදේශ වෙළඳාමේ සහ ලුණු ලබාගැනීමේ සියලු මුහුදු තොටුපළවල් අහිමි වී මුළුමනින්ම ගොඩබිමකට සීමාවීම", "රජුට ඔටුන්න අහිමිවීම", "බුදුදහම තහනම් වීම", "රජු මරා දැමීම", "ත්‍රිකුණාමලය, මඩකලපුව ඇතුළු සියලු වරායවල් අහිමිවීමෙන් උඩරට රාජ්‍යය ආර්ථික වශයෙන් ලන්දේසීන්ට යටත් විය."),
    q(T, "ලන්දේසීන් විසින් ලංකාවේ ප්‍රචලිත කරන ලද ක්‍රිස්තියානි ආගමික නිකාය කුමක්ද?", "ලන්දේසි රෙපරමාදු (Dutch Reformed / Protestant)", "රෝමානු කතෝලික", "ඇංග්ලිකානු", "මෙතෝදිස්ත", "වොල්වෙන්ඩාල් දේවස්ථානය ඇතුළු ලන්දේසි ප්‍රතිසංස්කරණ පල්ලි ඉදිකරමින් රෙපරමාදු ධර්මය ප්‍රචාරය කළහ."),
    q(T, "ක්‍රි.ව. 1795-1796 දී බ්‍රිතාන්‍යයන් විසින් ලංකාවේ ලන්දේසි බලප්‍රදේශ අල්ලා ගැනීමට හේතු වූ යුරෝපයේ සිදුවීම කුමක්ද?", "නැපෝලියන්ගේ ප්‍රංශ හමුදා නෙදර්ලන්තය (ලන්දේසිය) ආක්‍රමණය කර අල්ලා ගැනීම", "ප්‍රංශ විප්ලවය ආරම්භ වීම", "කාර්මික විප්ලවය", "ඇමරිකානු නිදහස් සටන", "නෙදර්ලන්තයේ පාලක පස්වන විලියම් කුමරු බ්‍රිතාන්‍යයට පලාගොස් ලන්දේසි යටත්විජිත ප්‍රංශයට නොදී බ්‍රිතාන්‍යයට භාරදෙන ලෙස 'කියු ලිපිය' (Kew Letter) නිකුත් කළේය."),
    q(T, "ක්‍රි.ව. 1796 පෙබරවාරි 16 වන දින බ්‍රිතාන්‍ය හමුදා හමුවේ කොළඹ කොටුව යටත් කළ ලන්දේසි ආණ්ඩුකාරවරයා කවුද?", "වැන් ඒන්ජල්බෙක් (Van Angelbeek)", "ඉමාන් විලෙම් ෆැල්ක්", "ජෝන් ඩොයිලි", "ෆෙඩ්රික් නෝර්ත්", "කිසිදු ප්‍රබල සටනකින් තොරව ලන්දේසි ආණ්ඩුකාර වැන් ඒන්ජල්බෙක් කොළඹ කොටුව බ්‍රිතාන්‍යයන්ට පවරා දුන්නේය."),
    q(T, "1796 සිට 1798 දක්වා ලංකාවේ මුහුදුබඩ ප්‍රදේශ පාලනය කරන ලද්දේ කුමන ආයතනය මගින්ද?", "බ්‍රිතාන්‍ය පෙරදිග වෙළඳ සමාගමේ මැඩ්‍රාස් (මදුරාසි) ආණ්ඩුව මගින්", "බ්‍රිතාන්‍ය කිරීටය මගින් සෘජුව", "ලන්දේසි සමාගම මගින්", "උඩරට රජු මගින්", "මුල් වසර දෙක තුළ මදුරාසි ආණ්ඩුව විසින් මෙරට පරිපාලනය මෙහෙයවන ලදී."),
    q(T, "මදුරාසි පාලනය විසින් ලංකාවේ බදු එකතු කිරීම සඳහා දකුණු ඉන්දියාවෙන් ගෙන්වන ලද නිලධාරීන් හැඳින්වූයේ කුමන නමින්ද?", "ආමුල්දාර්වරු (Aumildars)", "මුදලිවරු", "විදෝර්වරු", "තෝම්බුකරුවෝ", "ආමුල්දාර්වරුන්ගේ දරුණු බදු අයකිරීම් සහ ස්වදේශිකයන්ට කළ තාඩන පීඩන නිසා මෙරට ජනතාව දැඩි ලෙස කෝපයට පත් වූහ."),
    q(T, "ක්‍රි.ව. 1797 දී බ්‍රිතාන්‍ය මදුරාසි පාලනයට එරෙහිව වෙරළබඩ ප්‍රදේශවල මහා ජනතා කැරැල්ලක් ඇතිවීමට බලපෑ ප්‍රධාන හේතුව කුමක්ද?", "පොල් ගස් බද්ද පැනවීම සහ ආමුල්දාර්වරුන්ගේ පීඩාකාරී පාලනය", "ලුණු බද්ද", "කුරුඳු ගැලවීම", "ආගමික ගැටලු", "සෑම පොල් ගසකටම රිදී කාසි එකහමාරක අධික බද්දක් පැනවීම නිසා රයිගම, පස්දුන් කෝරළය ඇතුළු ප්‍රදේශවල ජනතාව කැරලි ගැසූහ."),
    q(T, "1797 වෙරළබඩ කැරැල්ලෙන් පසු මදුරාසි ආණ්ඩුවේ වැරදි ක්‍රියාදාමයන් විමර්ශනය කිරීමට පත්කළ කමිටුව කුමක්ද?", "කර්නල් ඩි මියුරොන් කමිටුව (De Meuron Committee)", "කෝල්බෲක් කමිටුව", "කැමරන් කමිටුව", "සෝල්බරි කමිටුව", "ඩි මියුරොන්ගේ නිර්දේශ මත පොල් බද්ද අහෝසි කර ආමුල්දාර්වරුන් ඉවත් කර දේශීය මුදලිවරුන් නැවත පත් කරන ලදී."),
    q(T, "ක්‍රි.ව. 1798 දී ලංකාවේ ප්‍රථම බ්‍රිතාන්‍ය ආණ්ඩුකාරවරයා ලෙස පත්ව ආවේ කවුද?", "ෆ්‍රෙඩ්රික් නෝර්ත් සාමිවරයා (Frederick North)", "රොබට් බ්‍රවුන්රිග්", "තෝමස් මේට්ලන්ඩ්", "ජෝන් ඩොයිලි", "නෝර්ත් ආණ්ඩුකාරවරයාගේ කාලයේදී ලංකාව පෙරදිග වෙළඳ සමාගම සහ බ්‍රිතාන්‍ය කිරීටය එක්ව පාලනය කළ 'ද්විත්ව පාලනයක්' පැවතිණි."),
    q(T, "ක්‍රි.ව. 1802 දී අත්සන් තැබූ කුමන ගිවිසුම මගින් ලංකාවේ මුහුදුබඩ ප්‍රදේශ බ්‍රිතාන්‍ය කිරීටයේ සෘජු යටත්විජිතයක් (Crown Colony) බවට පත්වූයේද?", "ආමියන්ස් ගිවිසුම (Treaty of Amiens)", "පැරිස් ගිවිසුම", "වර්සායිල්ස් ගිවිසුම", "ලන්ඩන් ගිවිසුම", "බ්‍රිතාන්‍යය සහ ප්‍රංශය අතර අත්සන් කළ ආමියන්ස් ගිවිසුම මගින් ලංකාවේ බ්‍රිතාන්‍ය බලය ජාත්‍යන්තරව තහවුරු විය."),
    q(T, "ශ්‍රී වික්‍රම රාජසිංහ රජු උඩරට සිහසුනට පත්කිරීමට මුල්වූ බලගතු උඩරට මහාදිකාරම්වරයා කවුද?", "පිලිමතලව්වේ මහාදිකාරම්", "ඇහැලේපොළ අදිකාරම්", "මොල්ලිගොඩ අදිකාරම්", "කැප්පෙටිපොළ", "කන්නසාමි නම් 18 හැවිරිදි කුමාරයා ශ්‍රී වික්‍රම රාජසිංහ නමින් රජකමට පත්කළ පිලිමතලව්වේ පසුව රජු තමාට පාලනය කරගත නොහැකි වූ විට රජුට විරුද්ධ විය."),
    q(T, "ක්‍රි.ව. 1803 දී බ්‍රිතාන්‍ය ආණ්ඩුකාර ෆ්‍රෙඩ්රික් නෝර්ත් විසින් උඩරට ආක්‍රමණය කිරීම සඳහා යැවූ හමුදා සේනාංකය මෙහෙයවූයේ කවුද?", "මේජර් ජෙනරාල් මැක්ඩොවල් (MacDowall)", "කර්නල් බාබුට්", "මේජර් ඩේවි", "ජෝන් ඩොයිලි", "මහනුවරට ඇතුළු වූ බ්‍රිතාන්‍ය හමුදාව උඩරට වැසියන්ගේ ගරිල්ලා ප්‍රහාර හා උණ රෝගය හමුවේ දරුණු ලෙස පරාජයට පත් විය."),
    q(T, "1803 පළමු ඉංග්‍රීසි-උඩරට යුද්ධයේදී මහනුවර රැඳී සිටි මේජර් ඩේවිගේ බ්‍රිතාන්‍ය සේනාංකය මුළුමනින්ම සමූලඝාතනය වූ ස්ථානය කුමක්ද?", "වාගොල්ලේදී (වටපුලුව / ගැටඹේ අසල)", "හඟුරන්කෙත", "බලන", "ගැටබේ", "මහවැලි ගඟෙන් එතෙර වීමට නොහැකිව කොටුවූ බ්‍රිතාන්‍ය සෙබළුන් උඩරට හමුදාව හමුවේ යටත් වූ පසු මරා දැමිණි."),
    q(T, "සිංහල භාෂාව, සිරිත් විරිත් මැනවින් ඉගෙන ගෙන උඩරට ප්‍රධානීන් අතර රහස් ඔත්තු ජාලයක් මෙහෙයවූ බ්‍රිතාන්‍ය සිවිල් නිලධාරියා කවුද?", "ජෝන් ඩොයිලි (John D'Oyly)", "රොබට් බ්‍රවුන්රිග්", "තෝමස් මේට්ලන්ඩ්", "ජේම්ස් කැස්ටන්", "සිංහල කවි ලිවීමට පවා සමත් වූ ඩොයිලි උඩරට රදළයන් සහ රජු අතර භේද ඇතිකිරීමට ප්‍රධාන කාර්යභාරයක් ඉටු කළේය."),
    q(T, "ශ්‍රී වික්‍රම රාජසිංහ රජු විසින් මහනුවර නගරය අලංකාර කිරීම සඳහා කරවන ලද විශිෂ්ට නිර්මාණය කුමක්ද?", "කිරිමුහුද (නුවර වැව) සහ පත්තිරිප්පුව", "මඟුල් මඩුව", "දළදා මාලිගාව", "ලංකාතිලකය", "දේවේන්ද්‍ර මූලාචාරී ලවා කරවන ලද නුවර වැව සහ අටපට්ටම් හැඩැති පත්තිරිප්පුව අදටත් මහනුවර නගරයේ අභිමානයයි."),
    q(T, "ශ්‍රී වික්‍රම රාජසිංහ රජු සමග විරසක වී ඉංග්‍රීසීන් වෙත පලාගිය දෙවන මහාදිකාරම්වරයා කවුද?", "ඇහැලේපොළ මහාදිකාරම්", "පිලිමතලව්වේ", "මොල්ලිගොඩ", "කැප්පෙටිපොළ", "සබරගමුවේ ඇතිවූ කැරැල්ලකින් පසු ඇහැලේපොළ ඉංග්‍රීසීන් වෙත පලාගිය අතර රජු විසින් ඔහුගේ බිරිඳ සහ දරුවන් අතිශය කෲර ලෙස ඝාතනය කරවන ලදී."),
    q(T, "1815 දී බ්‍රිතාන්‍යයන් උඩරට ආක්‍රමණය කිරීමට ආසන්නතම ක්ෂණික හේතුව ලෙස ප්‍රයෝජනයට ගත් සිදුවීම කුමක්ද?", "උඩරටට ගිය මුහුදුබඩ වෙළඳුන් දස දෙනෙකුගේ අතපය කපා දැමීමේ සිද්ධිය", "ඇහැලේපොළ කුමාරිහාමි ඝාතනය", "ඩොයිලි පැහැරගැනීම", "වෙළඳ ගිවිසුම කඩවීම", "බ්‍රිතාන්‍ය යටත්වැසියන් වූ වෙළඳුන් ඔත්තුකරුවන් යැයි සැකකර රජු විසින් අතපය කපා දැමීම යුද්ධ ප්‍රකාශ කිරීමට නිදහසට කරුණක් කරගන්නා ලදී."),
    q(T, "ක්‍රි.ව. 1815 පෙබරවාරි 18 වන දින ශ්‍රී වික්‍රම රාජසිංහ රජු බ්‍රිතාන්‍ය හමුදා විසින් අත්අඩංගුවට ගනු ලැබුවේ කුමන ස්ථානයේදීද?", "මැදමහනුවර බෝමුරේදී", "හඟුරන්කෙතදී", "තෙල්දෙණියේදී", "කුණ්ඩසාලේදී", "එක්නේලිගොඩ නිලමේ ප්‍රමුඛ පිරිස විසින් රජු සහ බිසෝවරුන් බෝමුරේ උඩුපිටිය ආරච්චිගේ නිවසේදී අල්ලා බ්‍රිතාන්‍යයන්ට භාර දෙන ලදී."),
    q(T, "අත්අඩංගුවට ගත් ශ්‍රී වික්‍රම රාජසිංහ රජු බ්‍රිතාන්‍යයන් විසින් පිටුවහල් කරන ලද්දේ කුමන ස්ථානයටද?", "ඉන්දියාවේ මදුරාසිය අසල වෙල්ලෝර් (Vellore) කොටුවට", "මොරිෂස් දූපතට", "අන්දමන් දූපතට", "ශාන්ත හෙලේනාවට", "1832 දී මියයන තෙක්ම ශ්‍රී වික්‍රම රාජසිංහ රජු වෙල්ලෝර් කොටුවේ සිරකරුවෙකු ලෙස රඳවා තබන ලදී."),
    q(T, "ඓතිහාසික උඩරට ගිවිසුම (Kandyan Convention) අත්සන් තබන ලද දිනය සහ ස්ථානය කුමක්ද?", "1815 මාර්තු 2 වන දින මහනුවර මඟුල් මඩුවේදී", "1815 පෙබරවාරි 18 කොළඹදී", "1818 ජනවාරි 1 මහනුවරදී", "1803 ජූනි 23 මහනුවරදී", "ආණ්ඩුකාර රොබට් බ්‍රවුන්රිග් සහ උඩරට ප්‍රධාන රදළයන් අතර මෙම ඓතිහාසික ගිවිසුම අත්සන් කෙරිණි."),
    q(T, "1815 උඩරට ගිවිසුමේ අන්තර්ගත වූ ඉතාම වැදගත් 5 වන වගන්තිය කුමක්ද?", "බුද්ධ ශාසනය හා දේවාල චාරිත්‍ර වාරිත්‍ර ආරක්ෂා කොට පවත්වාගෙන යාම", "ක්‍රිස්තියානි ධර්මය ප්‍රචාරය කිරීම", "රජු නැවත පත්කිරීම", "බදු අහෝසි කිරීම", "බුදුදහම, සංඝයා වහන්සේ සහ විහාර දේවාල පෙර පරිදිම බ්‍රිතාන්‍ය රජය විසින් ආරක්ෂා කරන බවට 5 වන වගන්තියෙන් පොරොන්දු විය."),
    q(T, "උඩරට ගිවිසුම අත්සන් කිරීමට පෙර මඟුල් මඩුවේ ඔසවා තිබූ බ්‍රිතාන්‍ය ධජය බිම හෙළා සිංහල ධජය එසවූ විරෝදාර හිමිපාණන් කවුද?", "වාරියපොළ ශ්‍රී සුමංගල අනුනාහිමි", "කුඩාපොළ හිමි", "මිගෙට්ටුවත්තේ ගුණානන්ද හිමි", "හික්කඩුවේ ශ්‍රී සුමංගල හිමි", "ගිවිසුම අත්සන් කිරීමට පෙර රටේ ස්වෛරීභාවය බ්‍රිතාන්‍යයට නොපැවරෙන බව ප්‍රකාශ කරමින් උන්වහන්සේ නිර්භීතව බ්‍රිතාන්‍ය ධජය පාගා දැමූහ."),
    q(T, "1815 උඩරට ගිවිසුමෙන් පසු මුළු ශ්‍රී ලංකාවටම අත්වූ ඓතිහාසික ඉරණම කුමක්ද?", "වසර 2300 කට අධික අඛණ්ඩ රාජාවලිය නිමාවී මුළු දිවයිනම ප්‍රථම වරට සම්පූර්ණයෙන්ම විදේශීය පාලනයට නතුවීම", "රට නිදහස් රාජ්‍යයක් වීම", "වෙරළබඩ පමණක් නිදහස් වීම", "ලන්දේසීන් නැවත පැමිණීම", "ක්‍රි.පූ. 543 විජය රජුගේ සිට පැවති ස්වදේශික රාජ්‍යත්වය අවසන් වී මුළු ලංකාවම බ්‍රිතාන්‍ය අධිරාජ්‍යයේ යටත්විජිතයක් බවට පත්විය."),
    q(T, "1815 ගිවිසුමෙන් වසර දෙකක් යන්නට මත්තෙන් 1817-1818 දී උඩරට ජනතාව බ්‍රිතාන්‍ය පාලනයට එරෙහිව නැගී සිටි මහා නිදහස් සටන හැඳින්වෙන්නේ කුමක් ලෙසද?", "1818 ඌව-වෙල්ලස්ස මහා නිදහස් සංග්‍රාමය (කැරැල්ල)", "මාතලේ කැරැල්ල", "1797 කැරැල්ල", "මුල්ලේරියා සටන", "බ්‍රිතාන්‍ය පාලනයෙන් රට මුදාගෙන ස්වදේශික රජෙකු පත්කර ගැනීමේ අරමුණින් ඌව-වෙල්ලස්ස කේන්ද්‍ර කරගෙන මෙම මහා සංග්‍රාමය ඇවිලී ගියේය."),
    q(T, "1817 දී ඌව-වෙල්ලස්සේ ජනතාව අතර බ්‍රිතාන්‍ය විරෝධය ඇවිලවීමට හේතු වූ බ්‍රිතාන්‍ය පරිපාලනමය ක්‍රියාව කුමක්ද?", "මුස්ලිම් ජාතික හජ්ජි මරික්කාර් නැමැත්තා වෙල්ලස්සේ මුහන්දිරම්වරයා ලෙස පත්කිරීම", "පොල් බද්ද පැනවීම", "දළදා වහන්සේ පැහැරගැනීම", "රජු මරා දැමීම", "සාම්ප්‍රදායික සිංහල රදළ පාලනය වෙනුවට ජනතාව අකමැති බාහිර පුද්ගලයෙකු බදු එකතු කිරීමට පත්කිරීමෙන් ජනතාව ප්‍රකෝප විය."),
    q(T, "1817 දී ඌව-වෙල්ලස්ස කැරැල්ල මර්දනය කිරීමට ගොස් කැරලිකරුවන් අතින් ඝාතනය වූ බ්‍රිතාන්‍ය උප ඒජන්තවරයා කවුද?", "සිල්වෙස්ටර් ඩග්ලස් විල්සන් (Sylvester Douglas Wilson)", "මේජර් ඩේවි", "ජෝන් ඩොයිලි", "කපිතාන් බ්‍රවුන්රිග්", "විල්සන් ඝාතනය වීමත් සමග කැරැල්ල මුළු උඩරට පුරාම ලැව්ගින්නක් සේ පැතිර ගියේය."),
    q(T, "ඌව-වෙල්ලස්ස කැරැල්ලේදී සිංහලේ රජු ලෙස පෙනී සිටිමින් කැරැල්ලට නායකත්වය දුන්නේ කවුද?", "විල්බාවේ (දුරෙයිසාමි / දොරේසාමි)", "කැප්පෙටිපොළ", "මඩුගල්ලේ", "ඇහැලේපොළ", "තමා රාජකීය උරුමක්කාරයෙකු බව පවසමින් විල්බාවේ රජු ලෙස පෙනී සිටිමින් ජනතාව සංවිධානය කළේය."),
    q(T, "ඌව-වෙල්ලස්ස කැරැල්ල මර්දනය කිරීමට බ්‍රිතාන්‍යයන් විසින් යවන ලද නමුත් කැරලිකරුවන්ගේ පැත්ත ගෙන නායකත්වය දුන් විරුවා කවුද?", "මොනරවිල කැප්පෙටිපොළ දිසාව", "මොල්ලිගොඩ", "ඇහැලේපොළ", "පිලිමතලව්වේ", "ඉංග්‍රීසීන් දුන් තුවක්කු හා වෙඩි බෙහෙත් නැවත බ්‍රිතාන්‍ය කඳවුරට හරවා යවා කැප්පෙටිපොළ ජාතික නිදහස් සටනේ අසහාය නායකයා බවට පත්විය."),
    q(T, "කැප්පෙටිපොළ නිලමේ සමග එක්ව 1818 නිදහස් සටනට නායකත්වය දුන් අනෙකුත් ප්‍රධාන උඩරට විරුවන් කවුරුන්ද?", "මඩුගල්ලේ දිසාව, කිවුලේගෙදර මොහොට්ටාල, කොහුකුඹුරේ රටේරාල සහ බූටෑවේ රටේරාල", "මොල්ලිගොඩ සහ එක්නේලිගොඩ", "ධර්මපාල සහ දොන් ජුවන්", "ඩොයිලි සහ නෝර්ත්", "මෙම විරුවන් උඩරට විවිධ දිසාවන්හි බ්‍රිතාන්‍ය හමුදාවන්ට එරෙහිව වීරෝදාර සටන් මෙහෙයවූහ."),
    q(T, "1818 කැරැල්ලේදී උඩරට ජනතාවගේ සටන්කාමීත්වය උච්චතම අවස්ථාවට පත්කළ සංකේතාත්මක සිදුවීම කුමක්ද?", "දළදා වහන්සේ සඟවාගෙන කැරලිකරුවන් අතට පත්වීම", "කොළඹ කොටුව වැටලීම", "නැව් ගිනිබත් කිරීම", "බ්‍රවුන්රිග් පලායාම", "දළදා හිමි අයිති තැනැත්තා රටේ නියම පාලකයා බවට පැවති විශ්වාසය නිසා දළදා වහන්සේ කැරලිකරුවන් සතුවීමත් සමග මුළු උඩරටම කැරැල්ලට එක්විය."),
    q(T, "1818 කැරැල්ල මර්දනය කිරීම සඳහා බ්‍රිතාන්‍ය ආණ්ඩුකාර රොබට් බ්‍රවුන්රිග් විසින් අනුගමනය කළ අමානුෂික උපක්‍රමය කුමක්ද?", "දැවී ගිය භූමි ප්‍රතිපත්තිය (Scorched Earth Policy)", "සමාව දීම", "සාම සාකච්ඡා පැවැත්වීම", "බදු අඩු කිරීම", "වයස 18 ට වැඩි සියලු පිරිමින් මරා දැමීම, ගෙවල්, කුඹුරු, වැව් අමුණු සහ පළතුරු ගස් ගිනිබත් කර විනාශ කරමින් මුළු ඌව-වෙල්ලස්සම සාගතයකට ඇද දැමීය."),
    q(T, "1818 නොවැම්බර් 25 වන දින මහනුවර බෝගම්බරදී බ්‍රිතාන්‍යයන් විසින් හිස ගසා මරා දමන ලද අසහාය නිදහස් සටන්කාමියා කවුද?", "මොනරවිල කැප්පෙටිපොළ දිසාව", "ඇහැලේපොළ", "මොල්ලිගොඩ", "විල්බාවේ", "මරණය හමුවේ කිසිදු බියක් නොදක්වා දළදා වහන්සේ සිහිකරමින් තම හිස ගසන්නාට බෙල්ල පෑ කැප්පෙටිපොළගේ හිස්කබල පසුව එංගලන්තයේ කෞතුකාගාරයකට ගෙන යන ලදී."),
    q(T, "කැප්පෙටිපොළ නිලමේගේ හිස්කබල බ්‍රිතාන්‍යයේ සිට නැවත ශ්‍රී ලංකාවට රැගෙන විත් මහනුවර ස්මාරකයක තැන්පත් කළේ කුමන වර්ෂයේදීද?", "ක්‍රි.ව. 1954 දී (නිදහසින් පසු)", "ක්‍රි.ව. 1948 දී", "ක්‍රි.ව. 1972 දී", "ක්‍රි.ව. 1931 දී", "එඩින්බරෝ කෞතුකාගාරයේ තබා තිබූ මෙම ඓතිහාසික හිස්කබල නැවත මෙරටට ගෙනැවිත් මහනුවර මහමළුවේ තැන්පත් කරන ලදී."),
    q(T, "1818 කැරැල්ල පරාජය වීමෙන් පසු බ්‍රිතාන්‍යයන් විසින් උඩරට පාලනය මුළුමනින්ම තමන් සතු කරගනිමින් නිකුත් කළ ප්‍රකාශනය කුමක්ද?", "1818 නොවැම්බර් ප්‍රකාශනය (1818 Proclamation)", "1815 ගිවිසුම", "කෝල්බෲක් ආඥාව", "ආණ්ඩුක්‍රම පනත", "1815 ගිවිසුමේ උඩරට රදළයන්ට දුන් වරප්‍රසාද සහ බුදුදහමට දුන් ආරක්ෂාව කප්පාදු කර බ්‍රිතාන්‍ය රජයේ පරම අධිකාරිය තහවුරු කරන ලදී."),
    q(T, "ක්‍රි.ව. 1829 දී ශ්‍රී ලංකාවේ පරිපාලන, මූල්‍ය හා අධිකරණ ප්‍රතිසංස්කරණ නිර්දේශ කිරීම සඳහා පත්කළ රාජකීය කොමිසමේ සාමාජිකයන් දෙදෙනා කවුද?", "ඩබ්ලිව්. එම්. ජී. කෝල්බෲක් සහ චාල්ස් හේ කැමරන්", "සෝල්බරි සහ ඩොනමෝර්", "නෝර්ත් සහ බ්‍රවුන්රිග්", "මැකලම් සහ මැනිං", "කෝල්බෲක් විසින් පරිපාලනය හා ආර්ථිකයද, කැමරන් විසින් අධිකරණ පද්ධතියද විමර්ශනය කරන ලදී."),
    q(T, "1833 කෝල්බෲක්-කැමරන් ප්‍රතිසංස්කරණ මගින් මෙරට ව්‍යවස්ථාදායක කටයුතු සඳහා පිහිටුවන ලද ආයතන දෙක මොනවාද?", "විධායක සභාව සහ ව්‍යවස්ථාදායක සභාව", "රාජ්‍ය මන්ත්‍රණ සභාව සහ පාර්ලිමේන්තුව", "සෙනෙට් සභාව සහ නියෝජිත මන්ත්‍රී මණ්ඩලය", "ජාතික රාජ්‍ය සභාව සහ කැබිනට් මණ්ඩලය", "ආණ්ඩුකාරවරයාගේ අභිමතය පරිදි පැවති ඒකාධිපති පාලනය සීමා කර උපදෙස් ලබාගැනීමට මෙම සභා දෙක පිහිටුවන ලදී."),
    q(T, "1833 දී පිහිටුවන ලද ව්‍යවස්ථාදායක සභාවේ (Legislative Council) මුළු සාමාජික සංඛ්‍යාව කීයද?", "15 කි (නිලලත් 9 ක් සහ නිලනොලත් 6 ක්)", "10 කි", "20 කි", "30 කි", "නිලනොලත් සාමාජිකයන් 6 දෙනාගෙන් 3 ක් යුරෝපීයයන් වූ අතර 3 ක් දේශීය ජාතීන් (සිංහල, දෙමළ, බර්ගර්) නියෝජනය කළහ."),
    q(T, "1833 දී කෝල්බෲක් ප්‍රතිසංස්කරණ මගින් ලංකාව මුල්වරට බෙදන ලද පරිපාලන පළාත් සංඛ්‍යාව කීයද?", "පළාත් 5 කට (බස්නාහිර, මධ්‍යම, දකුණ, උතුර, නැගෙනහිර)", "පළාත් 9 කට", "පළාත් 7 කට", "පළාත් 3 කට", "උඩරට සහ පහතරට ලෙස පැවති වෙනම පරිපාලනය අහෝසි කර මුළු දිවයිනම ඒකාබද්ධ කර පළාත් 5 කට බෙදා දිසාපතිවරුන් යටතට පත් කරන ලදී."),
    q(T, "කෝල්බෲක් ප්‍රතිසංස්කරණ මගින් අහෝසි කරන ලද, රජයට නොමිලේ ශ්‍රමය සැපයීමේ පාරම්පරික ක්‍රමය කුමක්ද?", "රාජකාරි ක්‍රමය (Rajakariya)", "බදු ක්‍රමය", "ගොවිතැන් ක්‍රමය", "කුල ක්‍රමය", "රාජකාරි ක්‍රමය අහෝසි කිරීම නිසා වැටුප් ලබන නිදහස් කම්කරු වෙළඳපොළක් බිහිවී වැවිලි ආර්ථිකය ආරම්භ කිරීමට මග පෑදිණි."),
    q(T, "කෝල්බෲක් නිර්දේශ අනුව රජයේ ආදායම් මාර්ගයක්ව පැවති කුමන වෙළඳ ඒකාධිකාරය අහෝසි කර නිදහස් වෙළඳාමට ඉඩ දෙන ලද්දේද?", "රජයේ කුරුඳු ඒකාධිකාරය (Cinnamon Monopoly)", "ලුණු ඒකාධිකාරය", "තේ ඒකාධිකාරය", "රබර් ඒකාධිකාරය", "කුරුඳු වෙළඳාම පෞද්ගලික අංශයට විවෘත කිරීමෙන් ධනවාදී වෙළඳ ආර්ථිකයක් ගොඩනැගීමට පදනම වැටිණි."),
    q(T, "කෝල්බෲක් නිර්දේශ මගින් අධ්‍යාපන ක්ෂේත්‍රයේ ඇති කළ ප්‍රධාන ප්‍රතිසංස්කරණය කුමක්ද?", "රජයේ පාසල්වල ඉංග්‍රීසි මාධ්‍යයෙන් අධ්‍යාපනය ලබාදීම සහ පාසල් කොමිසමක් පිහිටුවීම", "සිංහල මාධ්‍ය පමණක් ඉගැන්වීම", "සියලු පාසල් වැසීම", "පිරිවෙන් පමණක් පවත්වාගෙන යාම", "බ්‍රිතාන්‍ය පරිපාලනයට අවශ්‍ය ලිපිකරුවන් සහ කණිෂ්ඨ නිලධාරීන් බිහිකිරීම සඳහා ඉංග්‍රීසි අධ්‍යාපනය ප්‍රවර්ධනය කරන ලදී."),
    q(T, "චාල්ස් හේ කැමරන්ගේ නිර්දේශ අනුව 1833 දී මෙරට ස්ථාපිත කළ ඉහළම අධිකරණය කුමක්ද?", "ශ්‍රේෂ්ඨාධිකරණය (Supreme Court)", "අභියාචනාධිකරණය", "ප්‍රිවි කවුන්සිලය", "මහාධිකරණය", "දිවයින පුරා ඒකාකාරී නීති පද්ධතියක් ඇති කරමින් ශ්‍රේෂ්ඨාධිකරණය සහ දිසා අධිකරණ ජාලයක් ස්ථාපිත කරන ලදී."),
    q(T, "ක්‍රි.ව. 1840 දී බ්‍රිතාන්‍ය රජය විසින් සම්මත කළ 'ප්‍රකාශයට පත් නොකළ මුඩුබිම් ආඥා පනත' (Wasteland Ordinance) මගින් සිදුවූ දැවැන්ත විනාශය කුමක්ද?", "පාරම්පරික හිමිකම් ඔප්පු නොමැති සියලු හේන් සහ වනාන්තර රජයේ ඉඩම් බවට පවරාගෙන වැවිලිකරුවන්ට විකිණීම", "ගොවීන්ට නොමිලේ ඉඩම් දීම", "වගා බිම් ආරක්ෂා කිරීම", "වැව් අලුත්වැඩියා කිරීම", "ගැමියන් පරම්පරා ගණනාවක් තිස්සේ හේන් ගොවිතැන් කළ ඉඩම් අහිමි වී ඔවුන් අන්ත අසරණ තත්ත්වයට පත් විය."),
    q(T, "1840 මුඩුබිම් පනත යටතේ ගැමියන්ගෙන් පැහැරගත් ඉඩම් අක්කරයක් සුදු වැවිලිකරුවන්ට විකුණන ලද්දේ කුමන මුදලකටද?", "සිලිං පහකට (5 Shillings / රුපියල් 2.50 කට)", "පවුම් සියයකට", "රුපියල් දහසකට", "සිලිං පනහකට", "අතිශය සොච්චම් මුදලකට සරුසාර කඳුකර ඉඩම් සුදු ජාතිකයන්ට ලබාදී කෝපි සහ තේ වතු ආරම්භ කරන ලදී."),
    q(T, "1848 මාතලේ නිදහස් අරගලයට ක්ෂණික හේතුව වූයේ කුමන ආණ්ඩුකාරවරයා විසින් පනවන ලද අසාධාරණ බදු ප්‍රතිපත්තියද?", "ටොරින්ටන් සාමිවරයා (Lord Torrington)", "මැකලම්", "ග්‍රෙගරි", "වෝඩ්", "ලෝක ආර්ථික අවපාතය හමුවේ රජයේ හිඟය පියවා ගැනීමට ටොරින්ටන් සාමිවරයා සාමාන්‍ය ජනයා මත නව බදු 7 ක් පැටවීය."),
    q(T, "1848 දී ටොරින්ටන් සාමිවරයා විසින් පනවන ලද අසාධාරණ බදු අතරට අයත් නොවන්නේ කුමන බද්දද?", "ආදායම් බද්ද (Income Tax)", "තුවක්කු බද්ද සහ බල්ලන් බද්ද", "ඔරු බද්ද සහ කරත්ත බද්ද", "සාප්පු බද්ද සහ ඇඟ බද්ද (පාර බද්ද)", "තුවක්කු, බල්ලන්, ඔරු, කරත්ත, සාප්පු, මුද්දර සහ ඇඟ බද්ද යන බදු 7 පනවන ලද අතර ආදායම් බද්දක් එහි නොවීය."),
    q(T, "1848 පැනවූ ඇඟ බද්ද (Poll Tax) නොගෙවන්නේ නම් ජනතාවට කිරීමට සිදුවූයේ කුමක්ද?", "වසරකට දින 6 ක් රජයේ මහා මාර්ගවල නොමිලේ ශ්‍රමය සැපයීම", "සිරගත වීම", "රටින් පිටුවහල් වීම", "ඉඩම් රාජසන්තක වීම", "මෙය අහෝසි කරන ලද පැරණි රාජකාරි ක්‍රමය නැවත වටරවුමකින් පැටවීමක් ලෙස ගැමියෝ සැලකූහ."),
    q(T, "1848 කැරැල්ලේදී මාතලේ නගරය අල්ලාගෙන සිංහලේ රජු ලෙස ඔටුනු පැළඳුවේ කවුද?", "ගොන්ගාලේගොඩ බණ්ඩා (පෑලියගොඩ ඩේවිඩ්)", "වීර පුරන් අප්පු", "කුඩාපොළ හාමුදුරුවෝ", "දිනේෂ්", "දඹුලු රජමහා විහාරයේදී ගිරානෑගම ඉන්ද්‍රජෝති නාහිමියන්ගේ ආශිර්වාදයෙන් ගොන්ගාලේගොඩ බණ්ඩා 'ශ්‍රී වික්‍රම සර්වසිද්ධි' නමින් රජු ලෙස ප්‍රකාශයට පත් විය."),
    q(T, "1848 නිදහස් අරගලයේ ප්‍රධාන සෙන්පතියා ලෙස මාතලේ බ්‍රිතාන්‍ය කඳවුරට ප්‍රහාර එල්ල කළ වීරයා කවුද?", "වීර පුරන් අප්පු (ෆ්‍රැන්සිස්කු ප්‍රනාන්දු)", "ගොන්ගාලේගොඩ බණ්ඩා", "කුඩාපොළ හිමි", "හැන්සෙල්", "මොරටුවේ උපන් ෆ්‍රැන්සිස්කු ප්‍රනාන්දු හෙවත් වීර පුරන් අප්පු කැරලිකාර හමුදාවේ අගමැති හා ප්‍රධාන සෙන්පති ලෙස වීරෝදාර සටනක් කළේය."),
    q(T, "1848 කැරැල්ලේදී කැරලිකරුවන්ට රැකවරණය දුන් බවට හා ඔත්තු සැඟවූ බවට චෝදනා කර බ්‍රිතාන්‍යයන් විසින් සිවුරු පිටින්ම වෙඩි තබා ඝාතනය කළ හිමිපාණන් කවුද?", "කුඩාපොළ ශ්‍රී රාහුල හිමි", "වාරියපොළ සුමංගල හිමි", "මිගෙට්ටුවත්තේ ගුණානන්ද හිමි", "හික්කඩුවේ සුමංගල හිමි", "ටොරින්ටන්ගේ යුද නීතිය යටතේ කිසිදු සාධාරණ නඩු විභාගයකින් තොරව මහනුවරදී කුඩාපොළ හිමියන් ඝාතනය කිරීම බ්‍රිතාන්‍යයේ පවා දැඩි විවේචනයට ලක්විය."),
    q(T, "වීර පුරන් අප්පු බ්‍රිතාන්‍ය හමුදා අතට පත්ව වෙඩි තබා මරා දැමීමට පෙර ප්‍රකාශ කළ ඓතිහාසික අභිමානවත් වදන් පෙළ කුමක්ද?", "මා වැනි තවත් සිංහලයන් හතර දෙනෙකු සිටියා නම් මේ රටෙන් ඉංග්‍රීසීන් පලවා හරිනවා", "මට සමාව දෙන්න", "මම ආයෙත් කැරලි ගහන්නේ නෑ", "මගේ ජීවිතය බේරන්න", "1848 අගෝස්තු 8 දින මාතලේදී වෙඩි තැබීමට පෙර පුරන් අප්පු තම මව්බිම වෙනුවෙන් නිර්භීතව මෙම ප්‍රකාශය කළේය."),
    q(T, "1848 මාතලේ කැරැල්ලේදී කුරුණෑගල දිසාවේ සටන් මෙහෙයවූ ගොන්ගාලේගොඩ බණ්ඩාගේ සොහොයුරා කවුද?", "ඩිංගිරාල (ඩෙංගිරාල)", "පුරන් අප්පු", "දිනේෂ්", "බූටෑවේ රටේරාල", "කුරුණෑගල කච්චේරිය අල්ලාගෙන සටන් කළ ඩිංගිරාල පසුව බ්‍රිතාන්‍යයන් අතින් ප්‍රසිද්ධියේ වෙඩි තබා ඝාතනය කරන ලදී."),
    q(T, "1848 කැරැල්ල මර්දනය කිරීමේදී ටොරින්ටන් සාමිවරයා අනුගමනය කළ අතිශය ම්ලේච්ඡ ක්‍රියාමාර්ගය කුමක්ද?", "මාස ගණනාවක් යුද නීතිය (Martial Law) පනවා නඩු විභාග නොමැතිව මරණ දණ්ඩනය දීම සහ දේපළ රාජසන්තක කිරීම", "සාකච්ඡා මාර්ගයෙන් විසඳීම", "බදු අත්හිටුවීම", "ප්‍රදේශයෙන් ඉවත්ව යාම", "ටොරින්ටන්ගේ කෲර ක්‍රියාමාර්ග නිසා මිනිසුන් සිය ගණනක් ඝාතනයට ලක්වූ අතර දහස් ගණනකගේ ඉඩකඩම් කොල්ලකන ලදී."),
    q(T, "ටොරින්ටන් ආණ්ඩුකාරවරයාගේ කෲර ක්‍රියා ගැන කරුණු රැස්කර බ්‍රිතාන්‍ය පාර්ලිමේන්තුවට පැමිණිලි කිරීමට ලන්ඩනයට ගිය නීතිඥවරයා කවුද?", "ක්‍රිස්ටෝෆර් එලියට් සහ ජෝන් සෙල්බි", "ජේම්ස් පීරිස්", "පොන්නම්බලම් අරුණාචලම්", "ඩී. ඇස්. සේනානායක", "කොළඹ ඔබ්සර්වර් පුවත්පතේ කර්තෘ ක්‍රිස්ටෝෆර් එලියට් ඇතුළු පිරිසගේ හෙළිදරව්ව බ්‍රිතාන්‍ය පාර්ලිමේන්තුවේ මහත් ආන්දෝලනයක් ඇති කළේය."),
    q(T, "1848 ලංකාවේ සිදුවීම් විමර්ශනය කිරීම සඳහා බ්‍රිතාන්‍ය පාර්ලිමේන්තුවේ පත්කළ කමිටුවේ සභාපතිවරයා කවුද?", "හියුම් (Joseph Hume) සහ ටෙනන්ට්", "කෝල්බෲක්", "සෝල්බරි", "ඩොනමෝර්", "පාර්ලිමේන්තු පරීක්ෂණ කමිටුවේ නිර්දේශ අනුව ටොරින්ටන් සාමිවරයා ආණ්ඩුකාර ධුරයෙන් වහාම ආපසු එංගලන්තයට කැඳවන ලදී."),
    q(T, "1848 කැරැල්ලෙන් පසු බ්‍රිතාන්‍ය රජය විසින් ඉවත් කරගන්නා ලද බදු මොනවාද?", "බල්ලන් බද්ද, සාප්පු බද්ද සහ තුවක්කු බද්ද සංශෝධනය කිරීම", "සියලු බදු", "තේ බද්ද", "රේගු බද්ද", "ජනතා විරෝධය හමුවේ අසාධාරණ බදු රැසක් අහෝසි කිරීමට හෝ ලිහිල් කිරීමට රජයට සිදුවිය."),
    q(T, "1818 සහ 1848 නිදහස් අරගල අතර පැවති මූලික වෙනසක් වූයේ කුමක්ද?", "1818 අරගලය උඩරට සාම්ප්‍රදායික රදළයන් විසින්ද, 1848 අරගලය පහතරටින් පැමිණි පොදු ජන නායකයන් විසින්ද මෙහෙයවීම", "1848 දී ආයුධ නොතිබීම", "1818 දී බදු ප්‍රශ්න නොතිබීම", "1848 දී පෘතුගීසීන් සටන් කිරීම", "1848 දී පුරන් අප්පු, ගොන්ගාලේගොඩ බණ්ඩා වැනි සාමාන්‍ය පහතරට ජනතාව උඩරට ගැමියන් සමග අත්වැල් බැඳගෙන අධිරාජ්‍යවාදයට එරෙහිව සටන් වැදුණි."),
    q(T, "පෘතුගීසීන් විසින් ලංකාවේ ඉදිකරන ලද බලකොටු අතරට අයත් නොවන්නේ කුමක්ද?", "මාතර තාරකා කොටුව", "කොළඹ කොටුව", "මෙනිකඩවර කොටුව", "යාපනය කොටුව", "මාතර තාරකා කොටුව ඉදිකරන ලද්දේ ලන්දේසීන් විසිනි; අනෙක්වා පෘතුගීසීන් විසින් මුලින් ඉදිකරන ලදී."),
    q(T, "පෘතුගීසි ලංකාවේ අධිකරණ කටයුතු සහ නීතිය පසිඳලීම භාරව සිටි ප්‍රධාන නිලධාරියා කවුද?", "ඔයිදෝර් (Ouvidor)", "විදෝර්", "කැප්ටන්", "මුදලි", "නඩු විසඳීම සහ නීතිමය කටයුතු පාලනය කළ පෘතුගීසි ප්‍රධාන විනිසුරුවරයා ඔයිදෝර් ලෙස හැඳින්විණි."),
    q(T, "පෘතුගීසි යුගයේදී කොළඹ කොටුවේ පිහිටුවා තිබූ උසස් නාගරික පරිපාලන ආයතනය කුමක්ද?", "කැමරාව (Camara)", "කච්චේරිය", "මුහන්දිරම් සභාව", "ලෑන්ඩ් රཱඩ්", "නගර පාලනය සහ වෙළඳ නියාමනය සිදුකළ නාගරික සභාව කැමරාවයි."),
    q(T, "ලන්දේසීන් විසින් කුරුඳු වගාව ව්‍යාප්ත කිරීම සඳහා බස්නාහිර පළාතේ කළ ප්‍රධාන සංවර්ධනය කුමක්ද?", "මරදාන කුරුඳු වත්ත (Cinnamon Gardens) ඇතුළු කුරුඳු වතු ක්‍රමානුකූලව වගා කිරීම", "තේ වගාව", "කෝපි වගාව", "රබර් වගාව", "වනයේ ඉබේ වැවෙන කුරුඳු වෙනුවට ක්‍රමානුකූලව කුරුඳු වතු පිහිටුවා කුරුඳු තළන්නන් (සලාගම ප්‍රජාව) ලවා කුරුඳු නිෂ්පාදනය ඉහළ දැමීය."),
    q(T, "ලන්දේසි පාලන සමයේ අධ්‍යාපනය හා ආගමික කටයුතු පාලනය කළ පූජක මණ්ඩලය කුමක්ද?", "ස්කොලාර්ක් කොමිසම (Scholarck Commission)", "කෝල්බෲක් සභාව", "කැමරාව", "කච්චේරිය", "පාසල් පරීක්ෂා කිරීම, තෝම්බු පවත්වාගෙන යාම සහ රෙපරමාදු ආගම ඉගැන්වීම මෙම කොමිසම මගින් සිදු කෙරිණි."),
    q(T, "ශ්‍රී ලංකාවේ මුද්‍රණ ශිල්පය මුල්වරට හඳුන්වා දෙන ලද්දේ කුමන යුරෝපීය පාලන සමයේදීද?", "ලන්දේසි පාලන සමයේදී (ක්‍රි.ව. 1737 දී)", "පෘතුගීසි සමයේ", "ඉංග්‍රීසි සමයේ", "ප්‍රංශ සමයේ", "ක්‍රි.ව. 1737 දී ලන්දේසි ආණ්ඩුකාර වැන් ඉම්හොෆ් විසින් රජයේ මුද්‍රණාලය පිහිටුවා සිංහල හා දෙමළ ආගමික පොත්පත් මුද්‍රණය කරන ලදී."),
    q(T, "ලන්දේසි පාලන සමයේ මෙරට භාවිත වූ 'තුට්ටුව', 'චල්ලිය', 'දුද්ද' වැනි කාසි නිපදවා තිබුණේ කුමන ලෝහයෙන්ද?", "තඹ ලෝහයෙන් (Copper)", "රත්තරන් වලින්", "රිදී වලින්", "යකඩ වලින්", "ලන්දේසි VOC ලාංඡනය සහිත මෙම තඹ කාසි මෙරට එදිනෙදා වෙළඳාමේ බහුලව භාවිත විය."),
    q(T, "බ්‍රිතාන්‍ය පාලන සමයේ මුල් භාගයේදී මෙරට ප්‍රධාන ආදායම් මාර්ගයක් බවට පත් වූ වාණිජ වැවිලි බෝගය කුමක්ද?", "කෝපි (Coffee)", "තේ", "රබර්", "පොල්", "1830 දශකයේ සිට කඳුකරයේ කෝපි වගාව වේගයෙන් ව්‍යාප්ත වූ අතර ශ්‍රී ලංකාව ලොව ප්‍රමුඛතම කෝපි අපනයනකරුවෙකු බවට පත් විය."),
    q(T, "ශ්‍රී ලංකාවේ කෝපි වගාව මුළුමනින්ම විනාශ වී යාමට හේතු වූ 1870 දශකයේ ඇතිවූ වසංගතය කුමක්ද?", "හේමිලියා වස්ටැට්‍රික්ස් හෙවත් කෝපි කොළ මලකඩ රෝගය (Coffee Rust)", "පිටිපුස් රෝගය", "මුල් කුණුවීම", "පළඟැටි උවදුර", "කොළ මලකඩ දිලීර රෝගය නිසා මුළු දිවයිනේම කෝපි වතු විනාශ වූ අතර ඒ වෙනුවට තේ වගාව හඳුන්වා දෙන ලදී."),
    q(T, "පෘතුගීසීන් විසින් මෙරට කතෝලික ධර්මය ප්‍රචාරය කිරීම සඳහා මුලින්ම එවනු ලැබූ පූජක නිකාය කුමක්ද?", "ෆ්‍රැන්සිස්කානු නිකාය (Franciscans)", "ජේසුයිට් නිකාය", "ඩොමිනිකන් නිකාය", "ඔගස්ටීනියානු නිකාය", "1543 දී ජොආඕ ද විලා ද කොන්ඩේ පියතුමා ප්‍රමුඛ ෆ්‍රැන්සිස්කානු පූජකවරු කෝට්ටේ ධර්මපාල කුමරුට අධ්‍යාපනය ලබාදෙමින් කතෝලික දහම පැතිරවූහ."),
    q(T, "පෘතුගීසි පාලනයට එරෙහිව වෙරළබඩ ප්‍රදේශවල මහා ජනතා කැරැල්ලක් මෙහෙයවූ 'ජයසූරිය බණ්ඩාර' නමින් ප්‍රකට විරුවා කවුද?", "එදිරිල්ලේ රාළ (Edirille Rala / Domingo Correa)", "කන්ගාර ආරච්චි", "කුරුප්පු මුදලි", "ඇන්ටෝනියෝ බරෙටෝ", "මුලදී පෘතුගීසීන්ට සේවය කළ දොමින්ගෝ කොරෙයා පසුව එදිරිල්ලේ රාළ නමින් පෘතුගීසීන්ට එරෙහිව මහා සටනක් මෙහෙයවීය."),
    q(T, "එදිරිල්ලේ රාළගේ මරණයෙන් පසු පෘතුගීසීන්ට එරෙහිව සීතාවක හා මාතර පෙදෙස්වල සටන් මෙහෙයවූ ඔහුගේ සොහොයුරා කවුද?", "සීමන් කොරෙයා (Simao Correa)", "කන්ගාර ආරච්චි", "කුරුප්පු මුදලි", "දොන් ජුවන්", "සීමන් කොරෙයා පසුව පෘතුගීසීන්ට එරෙහිව උඩරට පළමුවන විමලධර්මසූරිය රජු සමග එක්ව සටන් කළේය."),
    q(T, "පෘතුගීසි ලංකාවේ විසූ අතිශය කුරිරුම කැප්ටන් ජනරාල්වරයා ලෙස ඉතිහාසයේ කුප්‍රකට වූයේ කවුද?", "ජෙරනිමෝ ද අසවේදු (Jeronimo de Azevedo)", "කොන්ස්තන්තීනු ද සා", "දොන් ලුවී", "ලොරෙන්සෝ ද අල්මේදා", "සිංහල ළදරුවන් කිඹුලන්ට කෑමට දැමීම ඇතුළු අතිමහත් කෲරත්වයන් කළ අසවේදු පසුව පෘතුගාලයේ සිරගෙදරකදී මියගියේය."),
    q(T, "ක්‍රි.ව. 1630 දී රන්දෙනිවෙල සටනේදී ඌව කුමරු වූ මහා අස්ථාන (දෙවන රාජසිංහ) හමුවේ පරාජය වී මියගිය පෘතුගීසි සෙන්පතියා කවුද?", "කොන්ස්තන්තීනු ද සා (Constantino de Sa)", "ජෙරනිමෝ ද අසවේදු", "දොන් හියෙරොනිමෝ", "දියෝගෝ ද මේලෝ", "බදුල්ල ආක්‍රමණය කර නගරය ගිනිබත් කළ කොන්ස්තන්තීනු ද සා රන්දෙනිවෙලදී ලස්කිරිඤ්ඤ හමුදාව සිංහල රජු සමග එක්වීම නිසා මුළු හමුදාවම සමග විනාශ විය."),
    q(T, "ක්‍රි.ව. 1638 දී දෙවන රාජසිංහ රජු හමුවේ පෘතුගීසි හමුදාව සහමුලින්ම විනාශ වූ ඓතිහාසික සටන කුමක්ද?", "ගන්නෝරුව සටන", "දන්තුරේ සටන", "මුල්ලේරියා සටන", "රන්දෙනිවෙල සටන", "දියෝගෝ ද මේලෝ කොවුටීඤ්ඤෝ ප්‍රමුඛ පෘතුගීසි හමුදාව ගන්නෝරුවේදී සහමුලින්ම වටලා විනාශ කර දමන ලදී."),
    q(T, "පෘතුගීසි පාලනයෙන් ලංකාවට හඳුන්වා දුන් ආහාර සහ කෘෂිකාර්මික භෝග නොවන්නේ කුමක්ද?", "තේ, කෝපි සහ රබර්", "අන්නාසි, පැපොල්, පේර සහ අලිගැටපේර", "මිරිස්, දුම්කොළ සහ තක්කාලි", "කජු, අල සහ මඤ්ඤොක්කා", "තේ, කෝපි සහ රබර් මෙරටට හඳුන්වා දුන්නේ බ්‍රිතාන්‍යයන් විසිනි; අනෙක් සියල්ල පෘතුගීසීන් ගෙනා භෝග වේ."),
    q(T, "ලන්දේසි පාලන සමයේ මෙරට ක්‍රියාත්මක වූ ඉහළම අධිකරණය කුමක්ද?", "රාඩ් වැන් ජස්ටීස් (Raad van Justitie / High Court)", "ලෑන්ඩ් රཱඩ්", "ස්ටැඩ්ස්රාඩ්", "කච්චේරි උසාවිය", "කොළඹ පිහිටි මෙම ලන්දේසි යුක්ති සභාව රෝම-ලන්දේසි නීතිය යටතේ සිවිල් සහ අපරාධ නඩු විභාග කළේය."),
    q(T, "ලන්දේසි පාලන සමයේ සුළු නාගරික අපරාධ හා ආරවුල් විසඳීම සඳහා කොළඹ නගරයේ පැවති උසාවිය කුමක්ද?", "නගර අධිකරණය හෙවත් ස්ටැඩ්ස්රාඩ් (Stadsraad / Town Court)", "ලෑන්ඩ් රཱඩ්", "ඉහළ උසාවිය", "යුද අධිකරණය", "කොළඹ කොටුව සහ පිටකොටුව ආශ්‍රිත පුරවැසියන්ගේ එදිනෙදා නඩු මෙම නාගරික අධිකරණය මගින් විභාග විය."),
    q(T, "ලන්දේසීන් විසින් කුරුඳු තළන්නන්ගෙන් කුරුඳු එකතු කිරීම පාලනය කිරීම සඳහා පත්කර තිබූ ප්‍රධාන නිලධාරියා කවුද?", "කුරුඳු කපිතාන් (Captain of Cinnamon)", "විදෝර්", "ඔයිදෝර්", "මුහන්දිරම්", "මහබද්ද හෙවත් කුරුඳු දෙපාර්තමේන්තුව භාරව සිටි මෙම නිලධාරියා කුරුඳු නිෂ්පාදනය දැඩි ලෙස අධීක්ෂණය කළේය."),
    q(T, "ලන්දේසි පාලන සමයේ මන්නාරම මුහුදු තීරයේ පවත්වාගෙන ගිය ප්‍රධාන ආදායම් මාර්ගයක් වූයේ කුමක්ද?", "මුතු කිමිදීම (Pearl Fishery) සහ හක්බෙලි කැඩීම", "තෙල් කැණීම", "රන් සේදීම", "දියමන්ති කැපීම", "මන්නාරම් බොක්කේ මුතු කිමිදීම මගින් ලන්දේසි පෙරදිග වෙළඳ සමාගම අතිවිශාල ලාභයක් ඉපැයීය."),
    q(T, "ලන්දේසීන් විසින් වල් අලින් අල්ලා විදේශයන්ට විකිණීම සඳහා යොදාගත් සම්ප්‍රදායික උගුල් ක්‍රමය කුමක්ද?", "ඇත් ගාල (Elephant Kraal)", "දැල් එලීම", "තුවක්කුවෙන් වෙඩි තැබීම", "අගල් කැපීම", "ගැමි ජනතාව ලවා දින ගණනක් වනයේ අලින් පන්නා ලී කඳන්වලින් තැනූ දැවැන්ත ඇත් ගාලට කොටු කර විදේශ වෙළඳුන්ට අලෙවි කළහ."),
    q(T, "ක්‍රි.ව. 1749 දී කොළඹ පිටකොටුවේ ලන්දේසීන් විසින් ඉදිකරන ලද සුප්‍රකට ලන්දේසි ප්‍රතිසංස්කරණ දේවස්ථානය කුමක්ද?", "වොල්වෙන්ඩාල් දේවස්ථානය (Wolvendaal Church)", "ශාන්ත අන්තෝනි පල්ලිය", "ශාන්ත ලුසියා ආසන දෙව්මැදුර", "ශාන්ත පාවුළු පල්ලිය", "ග්‍රීක කුරුසයක හැඩයෙන් කළුගලින් ඉදිකළ වොල්වෙන්ඩාල් පල්ලිය ලන්දේසි ගෘහ නිර්මාණ ශිල්පයේ විශිෂ්ට උරුමයකි."),
    q(T, "ලන්දේසි පාලනයෙන් සිංහල සමාජයට එක්වූ සංස්කෘතික අංගයක් නොවන්නේ කුමක්ද?", "බයිලා සහ කපිරිඤ්ඤා සංගීතය", "බුරුත හා තේක්ක දැවයෙන් කළ කැටයම් අල්මාරි සහ පුටු", "ලන්දේසි උළු සහ වරිච්චි ගෙවල්වල ඉස්තෝප්පුව (Verandah)", "බ්‍රෙඩ්ෆෲට් (දෙල්) සහ කොස් වගාව", "බයිලා සහ කපිරිඤ්ඤා සංගීතය පෘතුගීසි සම්භවයක් ඇති එකකි; ලන්දේසි නොවේ."),
    q(T, "ක්‍රි.ව. 1762 දී බ්‍රිතාන්‍යයන් විසින් උඩරට කීර්ති ශ්‍රී රාජසිංහ රජු හමුවට එවන ලද ප්‍රථම බ්‍රිතාන්‍ය දූතයා කවුද?", "ජෝන් පයිබස් (John Pybus)", "හියු බොයිඩ්", "රොබට් ඇන්ඩෲස්", "මැක්ඩොවල්", "ලන්දේසීන්ට එරෙහිව උඩරට රජුගේ ආධාර ලබාගැනීමේ අරමුණින් මදුරාසි ආණ්ඩුව විසින් පයිබස් එවන ලද නමුත් සාර්ථක ගිවිසුමකට එළඹීමට නොහැකි විය."),
    q(T, "ක්‍රි.ව. 1782 දී ත්‍රිකුණාමල වරාය අල්ලා ගැනීමෙන් පසු උඩරට රජු හමුවීමට පැමිණි දෙවන බ්‍රිතාන්‍ය දූතයා කවුද?", "හියු බොයිඩ් (Hugh Boyd)", "ජෝන් පයිබස්", "රොබට් ඇන්ඩෲස්", "ඩොයිලි", "රාජාධිරාජසිංහ රජු හමුවීමට ගිය බොයිඩ්ටද නිල එකඟතාවයකට එළඹීමට නොහැකි විය."),
    q(T, "ක්‍රි.ව. 1795 දී උඩරට රජු සමග වෙළඳ හා ආරක්ෂක ගිවිසුමක් සාකච්ඡා කිරීමට පැමිණි තෙවන බ්‍රිතාන්‍ය දූතයා කවුද?", "රොබට් ඇන්ඩෲස් (Robert Andrews)", "හියු බොයිඩ්", "ජෝන් පයිබස්", "මැක්ඩොවල්", "ඇන්ඩෲස් විසින් රජු සමග මූලික එකඟතාවයක් ඇතිකරගත් අතර පසුව බ්‍රිතාන්‍යයන් ලන්දේසි කොටු අල්ලාගත් පසු එම ගිවිසුම ක්‍රියාත්මක නොකළේය."),
    q(T, "ක්‍රි.ව. 1795 දී බ්‍රිතාන්‍ය හමුදා විසින් ලන්දේසීන්ගෙන් මුලින්ම අත්පත් කරගත් ලංකාවේ බලකොටුව කුමක්ද?", "ත්‍රිකුණාමල කොටුව (Fort Ostenburg & Fort Frederick)", "කොළඹ කොටුව", "ගාලු කොටුව", "යාපනය කොටුව", "ස්වභාවික ගැඹුරු වරායක් වූ ත්‍රිකුණාමලය නැගෙනහිර ඉන්දියානු නාවික ආධිපත්‍යයට අතිශය වැදගත් බැවින් බ්‍රිතාන්‍යයන් එය මුලින්ම අල්ලා ගත්තේය."),
    q(T, "1805 සිට 1811 දක්වා ලංකාවේ ආණ්ඩුකාරවරයා ලෙස සේවය කරමින් ජූරි සභා ක්‍රමය මෙරටට හඳුන්වා දුන්නේ කවුද?", "ශ්‍රීමත් තෝමස් මේට්ලන්ඩ් (Sir Thomas Maitland)", "ෆ්‍රෙඩ්රික් නෝර්ත්", "රොබට් බ්‍රවුන්රිග්", "ජෝන් ඩොයිලි", "නඩු විභාගවලදී ජනතාවගේ සහභාගීත්වය සහිත අපරාධ ජූරි ක්‍රමය 1811 දී මෙරටට හඳුන්වා දෙන ලද්දේ මේට්ලන්ඩ් විසිනි."),
    q(T, "උඩරට රාජධානිය අභ්‍යන්තරයෙන් දුර්වල කිරීමට ක්‍රියා කළ බ්‍රිතාන්‍ය සිවිල් නිලධාරී ජෝන් ඩොයිලි දැරූ නිල තනතුර කුමක්ද?", "දේශීය කටයුතු පිළිබඳ ප්‍රධාන භාෂා පරිවර්තක සහ සිවිල් කොමසාරිස් (Chief Translator & Resident)", "ආණ්ඩුකාරවරයා", "හමුදාපති", "අගවිනිසුරු", "ඩොයිලි විසින් සිංහල භාෂාවෙන් ලිපි ලියමින් උඩරට රදළයන් රජුට එරෙහිව පොළඹවා ගැනීමට කටයුතු කළේය."),
    q(T, "1811 දී ශ්‍රී වික්‍රම රාජසිංහ රජුට විරුද්ධව කුමන්ත්‍රණය කළ බවට චෝදනා ලබා හිස ගසා මරා දැමූ මහාදිකාරම්වරයා කවුද?", "පිලිමතලව්වේ මහාදිකාරම්", "ඇහැලේපොළ", "මොල්ලිගොඩ", "කැප්පෙටිපොළ", "රජු ඝාතනය කර රාජ්‍ය බලය අල්ලා ගැනීමට තැත් කළ බවට චෝදනා ඔප්පු වීමෙන් පිලිමතලව්වේ මරණ දණ්ඩනයට ලක්විය."),
    q(T, "පිලිමතලව්වේගේ මරණයෙන් පසු පළමු මහාදිකාරම් තනතුරට පත් වූයේ කවුද?", "ඇහැලේපොළ නිලමේ", "මොල්ලිගොඩ", "කැප්පෙටිපොළ", "පිලිමතලව්වේ කනිෂ්ඨ", "ඇහැලේපොළ පළමු අදිකාරම් බවටත්, මොල්ලිගොඩ දෙවන අදිකාරම් බවටත් රජු විසින් පත් කරන ලදී."),
    q(T, "ඇහැලේපොළ නිලමේගේ නායකත්වයෙන් 1814 දී රජුට එරෙහිව කැරැල්ලක් ඇතිවූ ප්‍රදේශය කුමක්ද?", "සබරගමුව දිසාව", "ඌව", "මාතලේ", "නුවරකලාවිය", "සබරගමුවේ දිසාව ලෙස කටයුතු කළ ඇහැලේපොළ එහිදී රජුට එරෙහිව ජනතාව කැරලි ගැස්වූ නමුත් රජුගේ හමුදා පැමිණි විට බ්‍රිතාන්‍යයන් වෙත පලා ගියේය."),
    q(T, "ඇහැලේපොළ පවුලේ ඛේදවාචකයේදී මද්දුම බණ්ඩාර කුමරු තම වැඩිමහල් සොහොයුරාට පැවසූ අමරණීය ප්‍රකාශය කුමක්ද?", "අයියණ්ඩිය නොහඬන්න, මරණයට බිය නොවන්න, සිංහල කොල්ලන් මැරෙන හැටි මම පෙන්වන්නම්", "අපි බේරෙමු", "මට බයයි", "රජුට දඬුවම් දෙන්න", "මද්දුම බණ්ඩාර කුමරු කිසිදු බියක් නොදක්වා වධකයා ඉදිරියට ගොස් බෙල්ල පාමින් දැක්වූ වීරත්වය සිංහල ඉතිහාසයේ අමරණීය විය."),
    q(T, "1815 උඩරට ආක්‍රමණයේදී බ්‍රිතාන්‍ය හමුදාවන්ට පහසුවෙන් මහනුවරට ඇතුළු වීමට හැකිවූයේ මන්ද?", "උඩරට රදළයන් සහ ජනතාව රජු කෙරෙහි දැඩි ලෙස කලකිරී සිටි බැවින් කිසිදු ප්‍රතිරෝධයක් නොදැක්වීම නිසා", "බ්‍රිතාන්‍යයන් විශාල හමුදාවක් ගෙන ඒම නිසා", "උඩරට ආයුධ නොතිබූ නිසා", "රජු කලින්ම රටින් පලාගොස් සිටි නිසා", "ශ්‍රී වික්‍රම රාජසිංහ රජුගේ කෲර ක්‍රියා නිසා ජනතාව සහ රදළයන් රජු අත්හැර දැමූ බැවින් බ්‍රිතාන්‍ය හමුදාව කිසිදු වෙඩිල්ලක් නොතබා මහනුවර අත්පත් කරගත්හ."),
    q(T, "ශ්‍රී වික්‍රම රාජසිංහ රජු සහ බිසෝවරුන් කොළඹට රැගෙන ඒමෙන් පසු ඉන්දියාවට ගෙන යන ලද්දේ කුමන නැවෙන්ද?", "කෝන්වොලිස් (HMS Cornwallis) යුද නැවෙන්", "වික්ටෝරියා", "ක්ලෙයාර්මොන්ට්", "අරෝරා", "1816 ජනවාරි 24 වන දින රජු ඇතුළු රාජකීය පවුල කොළඹින් නැව් නංවා මදුරාසියට පිටුවහල් කරන ලදී."),
    q(T, "1815 මාර්තු 2 උඩරට ගිවිසුමට අත්සන් තැබූ බ්‍රිතාන්‍ය ආණ්ඩුකාරවරයා කවුද?", "ශ්‍රීමත් රොබට් බ්‍රවුන්රිග් (Sir Robert Brownrigg)", "ෆ්‍රෙඩ්රික් නෝර්ත්", "තෝමස් මේට්ලන්ඩ්", "ජෝන් ඩොයිලි", "බ්‍රිතාන්‍ය රජු වෙනුවෙන් ආණ්ඩුකාර බ්‍රවුන්රිග් මෙම ගිවිසුමට අත්සන් තැබීය."),
    q(T, "උඩරට ගිවිසුමේ පළමු වගන්තියෙන් ප්‍රකාශයට පත් කරන ලද්දේ කුමක්ද?", "ශ්‍රී වික්‍රම රාජසිංහ රජු කුරිරු පාලකයෙකු බැවින් සිහසුනෙන් පහ කරන ලද බව සහ ඔහුගේ නායක්කාර් පවුලේ සියලු උරුමයන් අහෝසි කළ බව", "බුදුදහම රැකීම", "බදු අය කිරීම", "ඉංග්‍රීසි රජු පිළිගැනීම", "නායක්කාර් රාජවංශයේ අයිතිය අහෝසි කර උඩරට සිහසුන බ්‍රිතාන්‍ය රජුට පවරන ලදී."),
    q(T, "1815 උඩරට ගිවිසුමට අත්සන් කළ ප්‍රධාන උඩරට ප්‍රධානීන් අතරට අයත් නොවන්නේ කවුද?", "වීර පුරන් අප්පු", "ඇහැලේපොළ මහාදිකාරම්", "මොල්ලිගොඩ මහාදිකාරම්", "කැප්පෙටිපොළ දිසාව", "වීර පුරන් අප්පු 1848 නිදහස් සටනේ නායකයෙකු වූ අතර 1815 දී ඔහු ජීවත්ව සිටියේ නැත."),
    q(T, "1815 ගිවිසුමෙන් පසු බ්‍රිතාන්‍යයන් විසින් උඩරට පාලනය සඳහා මහනුවර පිහිටුවන ලද ආයතනය කුමක්ද?", "උඩරට නේවාසික මණ්ඩලය (Board of Commissioners in Kandy)", "ව්‍යවස්ථාදායක සභාව", "විධායක සභාව", "කච්චේරිය", "ජෝන් ඩොයිලිගේ ප්‍රධානත්වයෙන් යුත් නේවාසික මණ්ඩලයක් මගින් උඩරට පරිපාලනය මෙහෙයවන ලදී."),
    q(T, "1815 ගිවිසුමෙන් පසු බලාපොරොත්තු සුන්වූ උඩරට රදළයන් සහ භික්ෂූන් වහන්සේලා තුළ ඇතිවූ ප්‍රධාන කලකිරීම කුමක්ද?", "තමන් අපේක්ෂා කළ පරිදි සිංහල රජෙකු පත් නොවීම සහ බුදුදහමට ප්‍රමුඛත්වය නොලැබීම", "බදු අඩු නොවීම", "ඉඩම් නොලැබීම", "වෙළඳාම නතරවීම", "බ්‍රිතාන්‍යයන් රටේ පාලනය තමන් සතු කරගෙන රදළයන්ගේ බලතල කප්පාදු කිරීම ඔවුන්ගේ දැඩි කෝපයට හේතු විය."),
    q(T, "1817 දී ඌව-වෙල්ලස්ස කැරැල්ලේ ආරම්භක සටන් ඇතිවූ ප්‍රදේශය කුමක්ද?", "බදුල්ල සහ බිබිල (සොරබොර වැව ආශ්‍රිත පෙදෙස)", "මහනුවර", "මාතලේ", "කුරුණෑගල", "වෙල්ලස්සේ ජනතාව බදු එකතු කිරීමට පැමිණි බ්‍රිතාන්‍ය නිලධාරීන්ට විරෝධය පාමින් සටන ආරම්භ කළහ."),
    q(T, "කැප්පෙටිපොළ දිසාව කැරලිකරුවන් හා එක්වීමෙන් පසු කැරැල්ල වේගයෙන් ව්‍යාප්ත වූ පළාත් නොවන්නේ කුමක්ද?", "යාපනය සහ මන්නාරම", "ඌව සහ වෙල්ලස්ස", "මාතලේ සහ වලපනේ", "හත්කෝරළය සහ සබරගමුව", "උඩරට සිංහල ප්‍රදේශ පුරා කැරැල්ල පැතිර ගිය නමුත් උතුරු පළාතට එය බලපෑවේ නැත."),
    q(T, "1818 කැරැල්ලේදී බ්‍රිතාන්‍ය හමුදාවන්ට දැඩි ලෙස පක්ෂපාතීව කටයුතු කරමින් බ්‍රිතාන්‍ය පාලනය රැකදුන් උඩරට රදළයා කවුද?", "මොල්ලිගොඩ මහාදිකාරම්", "කැප්පෙටිපොළ", "මඩුගල්ලේ", "කිවුලේගෙදර", "සතර කෝරළය භාරව සිටි මොල්ලිගොඩ කැරැල්ලට එක් නොවී බ්‍රිතාන්‍යයන්ට පක්ෂපාතීව සිටි බැවින් කොළඹ සිට මහනුවරට බ්‍රිතාන්‍ය ආධාරක හමුදා ගෙන ඒමට හැකි විය."),
    q(T, "1818 දී බ්‍රිතාන්‍යයන් විසින් කැරැල්ල මෙහෙයවූ නායකයන්ගේ නම් සඳහන් කර නිකුත් කළ ගැසට් නිවේදනය කුමක්ද?", "රාජද්‍රෝහීන්ගේ ලැයිස්තුව (List of Traitors)", "සමාව දීමේ ලැයිස්තුව", "ඇමති ලැයිස්තුව", "විශ්‍රාමික ලැයිස්තුව", "කැප්පෙටිපොළ, මඩුගල්ලේ ඇතුළු නායකයන් 19 දෙනෙකු 'රාජද්‍රෝහීන්' ලෙස නම් කර ඔවුන්ගේ දේපළ රාජසන්තක කර අත්අඩංගුවට ගැනීමට ත්‍යාග ප්‍රකාශයට පත් කළේය."),
    q(T, "ශ්‍රී ලංකා රජය විසින් 1818 කැරැල්ලේ නායකයන් 'රාජද්‍රෝහීන්' යන ලේබලයෙන් නිදහස් කර 'ජාතික වීරයන්' ලෙස ප්‍රකාශයට පත් කළේ කුමන වර්ෂයේදීද?", "ක්‍රි.ව. 2016 දී (ජනාධිපති ප්‍රකාශනයකින්)", "ක්‍රි.ව. 1948 දී", "ක්‍රි.ව. 1972 දී", "ක්‍රි.ව. 1956 දී", "වසර 198 කට පසු බ්‍රිතාන්‍යයන් විසින් පනවන ලද රාජද්‍රෝහී ගැසට් නිවේදනය නිල වශයෙන් අවලංගු කර ඔවුන් ජාතික විරුවන් ලෙස නම් කරන ලදී."),
    q(T, "1818 කැරැල්ලෙන් පසු බ්‍රිතාන්‍යයන් විසින් සැකපිට අත්අඩංගුවට ගෙන මොරිෂස් දූපතට පිටුවහල් කරන ලද නායකයා කවුද?", "ඇහැලේපොළ මහා නිලමේ", "මොල්ලිගොඩ", "විල්බාවේ", "පිලිමතලව්වේ", "කැරැල්ලට සෘජුව සම්බන්ධ නොවූවද ඔහු කෙරෙහි සැක පහළ කළ බ්‍රිතාන්‍යයෝ ඇහැලේපොළ මොරිෂස් දූපතට පිටුවහල් කළ අතර 1829 දී ඔහු එහිදී මියගියේය."),
    q(T, "1818 නොවැම්බර් 21 ප්‍රකාශනය මගින් උඩරට සම්ප්‍රදායික පාලන ව්‍යුහයට කළ ප්‍රධාන හානිය කුමක්ද?", "උඩරට රදළයන් සතුව පැවති අධිකරණ හා බදු බලතල අහෝසි කර බ්‍රිතාන්‍ය නිලධාරීන් යටතට පත්කිරීම", "රදළයන්ට වැඩි බලතල දීම", "රජු නැවත පත්කිරීම", "සියලු නිලමේවරුන් මරා දැමීම", "රදළයන්ගේ බලය බිඳ දමා බ්‍රිතාන්‍ය ඒජන්තවරුන් (Government Agents) යටතේ සෘජු පරිපාලනයක් ස්ථාපිත කරන ලදී."),
    q(T, "කෝල්බෲක් කොමිසම පත්කිරීමට බ්‍රිතාන්‍ය රජය පෙළඹවූ ප්‍රධාන ආර්ථික අර්බුදය කුමක්ද?", "ලංකාවේ බ්‍රිතාන්‍ය පරිපාලන වියදම අධික වීම නිසා වාර්ෂිකව අයවැය හිඟයක් (Budget Deficit) පැවතීම", "ලංකාව ධනවත් වීම", "යුද්ධයක් ඇතිවීම", "ලන්දේසීන් ඉල්ලීම් කිරීම", "යටත්විජිතය පවත්වාගෙන යාමට බ්‍රිතාන්‍ය භාණ්ඩාගාරයෙන් මුදල් යැවීමට සිදුවීම නිසා වියදම් කපාහැර ආදායම් වැඩිකර ගැනීමේ ක්‍රම සෙවීමට කොමිසම පත් කරන ලදී."),
    q(T, "1833 කෝල්බෲක් ප්‍රතිසංස්කරණවලින් මෙරට ස්ථාපිත වූ විධායක සභාවේ (Executive Council) කාර්යභාරය කුමක්ද?", "ආණ්ඩුකාරවරයාට පරිපාලන තීරණ ගැනීමේදී උපදෙස් දීම", "නීති සම්පාදනය කිරීම", "නඩු ඇසීම", "යුද්ධ ප්‍රකාශ කිරීම", "ආණ්ඩුකාරවරයා, හමුදාපති, යටත්විජිත ලේකම්, මහා භාණ්ඩාගාරික ඇතුළු ජ්‍යෙෂ්ඨ නිලධාරීන්ගෙන් විධායක සභාව සමන්විත විය."),
    q(T, "1833 ව්‍යවස්ථාදායක සභාවට පත්කළ ප්‍රථම දේශීය නියෝජිතයන් තිදෙනා අයත් වූයේ කුමන ප්‍රජාවන්ටද?", "සිංහල, දෙමළ සහ බර්ගර්", "මුස්ලිම්, මැලේ සහ වැද්ද", "ඉංග්‍රීසි, ප්‍රංශ සහ ලන්දේසි", "ඉන්දියානු, චීන සහ ජාවා", "ජේ. ජී. පිලිප්ස් (සිංහල), ඒ. කුමාරස්වාමි (දෙමළ) සහ ජේ. ජී. හෙන්ඩර්සන් (බර්ගර්) නිලනොලත් සාමාජිකයන් ලෙස නම් කරන ලදී."),
    q(T, "කෝල්බෲක් ප්‍රතිසංස්කරණ මගින් මෙරට පුවත්පත් කලාවට සිදුවූ වැදගත් යහපත කුමක්ද?", "රාජ්‍ය නොවන පෞද්ගලික පුවත්පත් පළකිරීමට නිදහස ලැබීම", "පුවත්පත් තහනම් කිරීම", "ඉංග්‍රීසි පුවත්පත් පමණක් ඉඩදීම", "රජයේ පුවත්පත පමණක් පවත්වාගෙන යාම", "1834 දී 'ද කලම්බෝ ඔබ්සර්වර්' (The Colombo Observer) ඇතුළු ස්වාධීන පුවත්පත් ආරම්භ කිරීමට මග පෑදිණි."),
    q(T, "කෝල්බෲක් ප්‍රතිසංස්කරණ මගින් පිහිටුවන ලද 'ලංකා සිවිල් සේවය' (Ceylon Civil Service - CCS) සඳහා බඳවා ගැනීමේ ක්‍රමය කුමක්ද?", "විවෘත තරඟ විභාග සහ කුසලතාව පදනම් කරගත් ක්‍රමය (Merit System)", "ඥාති සංග්‍රහය", "මුදලට විකිණීම", "කුලය අනුව පත්කිරීම", "පරිපාලන නිලධාරීන් කුසලතාව අනුව විභාග මගින් බඳවා ගැනීමට පියවර ගන්නා ලදී."),
    q(T, "චාල්ස් හේ කැමරන්ගේ නිර්දේශ අනුව මෙරට සුළු සිවිල් නඩු සහ මුදල් ආරවුල් විසඳීමට පිහිටුවූ අධිකරණය කුමක්ද?", "ඉල්ලීම් උසාවිය (Court of Requests)", "ශ්‍රේෂ්ඨාධිකරණය", "මහාධිකරණය", "ප්‍රිවි කවුන්සිලය", "සුළු මුදල් ණය සහ ආරවුල් ඉක්මනින් විසඳා දීමට ඉල්ලීම් උසාවි පිහිටුවන ලදී."),
    q(T, "කැමරන්ගේ අධිකරණ ප්‍රතිසංස්කරණවල ප්‍රධාන මූලධර්මයක් වූයේ කුමක්ද?", "ජාතිය, කුලය හෝ ආගම නොබලා නීතිය ඉදිරියේ සියලු දෙනා සමාන ලෙස සැලකීම", "යුරෝපීයයන්ට විශේෂ නීති පැවතීම", "රදළයන්ට වෙනම උසාවි තිබීම", "පැරණි දඬුවම් ක්‍රම දිගටම තැබීම", "නීතියේ ආධිපත්‍යය (Rule of Law) සහ අධිකරණයේ ස්වාධීනත්වය මෙරටට හඳුන්වා දීමට කැමරන් කටයුතු කළේය."),
    q(T, "1840 මුඩුබිම් පනතට අමතරව 1848 දී ගැමි ජනතාවගේ ඉඩම් අහිමි කිරීමට බලපෑ තවත් ආඥා පනතක් කුමක්ද?", "1848 ඉඩම් ලියාපදිංචි කිරීමේ ආඥා පනත", "පොල් බදු පනත", "කුරුඳු පනත", "වතු පනත", "පාරම්පරික ලියකියවිලි නැති ඉඩම් සියල්ල රජය සතු කරමින් වැවිලි සමාගම්වලට විකිණීම වේගවත් විය."),
    q(T, "1848 ජූලි 6 වන දින කොළඹ බෝරැල්ලේදී ආණ්ඩුකාර ටොරින්ටන්ගේ බදු ප්‍රතිපත්තියට එරෙහිව දැවැන්ත ජනතා පෙළපාලියක් මෙහෙයවූයේ කවුද?", "ආචාර්ය ක්‍රිස්ටෝෆර් එලියට් (Dr. Christopher Elliott)", "ජේම්ස් පීරිස්", "පුරන් අප්පු", "ගොන්ගාලේගොඩ බණ්ඩා", "කොළඹ ඔබ්සර්වර් කර්තෘ එලියට් විසින් සිංහලෙන් අත්පත්‍රිකා මුද්‍රණය කර බෙදාහරිමින් දහස් ගණනක් ජනයා බෝරැල්ලට රැස්කර පෙත්සමක් ඉදිරිපත් කළේය."),
    q(T, "ගොන්ගාලේගොඩ බණ්ඩාගේ සැබෑ නම කුමක්ද?", "පෑලියගොඩ ඩේවිඩ් (David Peliyagoda)", "ෆ්‍රැන්සිස්කු ප්‍රනාන්දු", "දිනිස්", "කිරිබණ්ඩා", "කැලණිය පෑලියගොඩ ප්‍රදේශයේ උපන් ඩේවිඩ් උඩරටට ගොස් ගොන්ගාලේගොඩ බණ්ඩා නමින් පෙනී සිටිමින් නිදහස් සටන මෙහෙයවීය."),
    q(T, "වීර පුරන් අප්පුගේ උපන් ගම කුමක්ද?", "මොරටුව (Moratuwa)", "පානදුර", "කළුතර", "මාතලේ", "මොරටුවේ උපන් ඔහු කතෝලික ධර්මය ඇදහූ පවුලක උපත ලැබූ අයෙකු වූ අතර පසුව උඩරට නිදහස් අරගලයේ ප්‍රධාන සෙන්පතියා විය."),
    q(T, "1848 ජූලි 28 වන දින කැරලිකරුවන් විසින් ප්‍රහාර එල්ල කර අල්ලා ගන්නා ලද නගරය කුමක්ද?", "මාතලේ නගරය", "නුවරඑළිය", "බදුල්ල", "රත්නපුරය", "මාතලේ කච්චේරිය, තානායම සහ රජයේ කාර්යාල අල්ලාගෙන බදු ලේඛන ගිනිබත් කළහ."),
    q(T, "1848 කැරැල්ලේදී මාතලේ නගරය ආසන්නයේ බ්‍රිතාන්‍ය හමුදා සහ කැරලිකරුවන් අතර දරුණු ගැටුමක් සිදුවූ ස්ථානය කුමක්ද?", "වාරියපොළ වත්ත (Wariyapola Estate)", "ගන්නෝරුව", "බලන", "කඩුගන්නාව", "කපිතාන් ලලී ප්‍රමුඛ බ්‍රිතාන්‍ය හමුදාව විසින් වාරියපොළ වත්තේදී කැරලිකරුවන්ට වෙඩි තබා විසිරුවා හරින ලදී."),
    q(T, "කුඩාපොළ ශ්‍රී රාහුල හිමියන් ඝාතනය කිරීමට බ්‍රිතාන්‍ය හමුදා උසාවිය ඉදිරිපත් කළ ප්‍රධාන චෝදනාව කුමක්ද?", "ගොන්ගාලේගොඩ බණ්ඩා සැඟවී සිටි තැන දැන සිටියද රජයේ හමුදාවන්ට නොපැවසීම සහ කැරලිකරුවන්ට ආහාර සැපයීම", "තුවක්කු අතැතිව සටන් කිරීම", "බදු නොගෙවීම", "කොළඹට පහරදීම", "තොරතුරු හෙළි නොකිරීම නිසා කුඩාපොළ හිමියන් පැය කිහිපයක නඩු විභාගයකින් පසු මහනුවරදී සිවුරු පිටින් වෙඩි තබා ඝාතනය කෙරිණි."),
    q(T, "කුඩාපොළ හිමියන්ට වෙඩි තැබීම වැළැක්වීමට උත්සාහ කළ බ්‍රිතාන්‍ය රැජිනගේ අධිනීතිඥවරයා (Queen's Advocate) කවුද?", "හෙන්රි සෙල්බි (Henry Selby)", "ටොරින්ටන්", "ටෙනන්ට්", "කෝල්බෲක්", "සෙල්බි ආණ්ඩුකාර ටොරින්ටන් හමුවට ගොස් සාක්ෂි ප්‍රමාණවත් නොවන බැවින් වෙඩි නොතබන ලෙස ඉල්ලා සිටියද ටොරින්ටන් එය ප්‍රතික්ෂේප කළේය."),
    q(T, "1848 කැරැල්ලෙන් පසු අත්අඩංගුවට පත් ගොන්ගාලේගොඩ බණ්ඩාට දෙන ලද දඬුවම කුමක්ද?", "කසපහර 100 ක් ගසා මලක්කාවට (මැලේසියාවට) ජීවිතාන්තය දක්වා පිටුවහල් කිරීම", "එල්ලා මැරීම", "හිස ගසා දැමීම", "නිදහස් කිරීම", "මරණ දණ්ඩනය නියම වූ නමුත් පසුව ආණ්ඩුකාරවරයා විසින් එය ලිහිල් කර පිටුවහල් කරන ලද අතර 1849 දී ඔහු මලක්කාවේදී මියගියේය."),
    q(T, "1848 දී ටොරින්ටන් ආණ්ඩුකාරවරයාගේ ලේකම්වරයා (Colonial Secretary) ලෙස කටයුතු කළ සුප්‍රකට ලේඛකයා කවුද?", "ශ්‍රීමත් ජේම්ස් එමර්සන් ටෙනන්ට් (Sir James Emerson Tennent)", "ජෝන් ඩොයිලි", "ක්‍රිස්ටෝෆර් එලියට්", "කෝල්බෲක්", "ලංකාව පිළිබඳ විශිෂ්ට ඉතිහාස හා භූගෝලීය කෘතියක් සම්පාදනය කළ ටෙනන්ට් ද කැරැල්ල මර්දනයට සම්බන්ධ වීම නිසා රැකියාවෙන් ඉවත් කරන ලදී."),
    q(T, "1848 කැරැල්ලෙන් පසු බ්‍රිතාන්‍ය පාර්ලිමේන්තුවේ ඇතිවූ දැඩි විවේචන හේතුවෙන් ආණ්ඩුකාර ටොරින්ටන් සහ ටෙනන්ට් දෙදෙනාටම අත්වූ ඉරණම කුමක්ද?", "ඔවුන් දෙදෙනාම වහාම සිය ධුරවලින් ඉවත් කර එංගලන්තයට කැඳවීම", "ඔවුන්ට උසස්වීම් ලැබීම", "ඔවුන් ලංකාවේම රැඳී සිටීම", "ඔවුන් සිරගත කිරීම", "බ්‍රිතාන්‍ය අගමැති ලෝඩ් ජෝන් රසල් විසින් ටොරින්ටන් ආපසු කැඳවූ අතර ඒ වෙනුවට ශ්‍රීමත් ජෝර්ජ් ඇන්ඩර්සන් පත් කරන ලදී."),
    q(T, "1848 නිදහස් අරගලයේ ඓතිහාසික වැදගත්කම පිළිබඳ නිවැරදි ප්‍රකාශය කුමක්ද?", "එය යටත්විජිත බදු පීඩනයට හා ඉඩම් කොල්ලයට එරෙහිව පහතරට හා උඩරට පොදු ජනතාව එක්ව කළ ප්‍රථම ජනතා විමුක්ති අරගලයයි", "එය සාර්ථක වී රටට නිදහස ලැබීම", "එය උඩරට රදළයන් පමණක් කළ සටනක් වීම", "එය ආගමික යුද්ධයක් පමණක් වීම", "සාමාන්‍ය ජනයාගේ දුක්ගැනවිලි මුල්කරගෙන පහතරටින් නායකත්වය ලැබී මුළු රටම ඒකරාශී වූ මහජන නැගීසිටීමක් ලෙස 1848 අරගලය ඉතිහාසගත වේ."),
    q(T, "පෘතුගීසි පාලන සමයේ කෝට්ටේ ධර්මපාල රජුගේ පාලන බලය කොළඹ කොටුවට පමණක් සීමා වූ විට ජනතාව අතර ප්‍රකට වූ උපහාසාත්මක කියමන කුමක්ද?", "පරංගියා කෝට්ටේ ගියා වගේ", "කොළඹට හතයි කෝට්ටේට දොළහයි", "දොන් ජුවන්ගේ කෙරුවාව", "ඉඟුරු දී මිරිස් ගත්තා වගේ", "පෘතුගීසීන් කෝට්ටේ රාජධානිය අභ්‍යන්තරයට ඇතුළුවීමට ගත් නොමනා උපක්‍රම සහ අසාර්ථකත්වය උපහාසයට ලක්විය."),
    q(T, "ලන්දේසි පාලන සමයේ මෙරටට හඳුන්වා දුන් ප්‍රධාන මුදල් ඒකකය වූයේ කුමක්ද?", "රික්ස්ඩෝලර් (Rixdollar)", "පවුම", "රුපියල", "දිනාරය", "ලන්දේසි පෙරදිග වෙළඳ සමාගම විසින් නිකුත් කළ රික්ස්ඩෝලර් මුදල් ඒකකය බ්‍රිතාන්‍ය පාලනයේ මුල් භාගය දක්වාම භාවිත විය."),
    q(T, "ක්‍රි.ව. 1820 දී කොළඹ සහ මහනුවර යා කරමින් කඩුගන්නාව දුර්ගය ඔස්සේ ප්‍රධාන මහා මාර්ගය ඉදිකළ බ්‍රිතාන්‍ය ඉංජිනේරුවා කවුද?", "කැප්ටන් විලියම් ෆ්‍රැන්සිස් ඩෝසන් (Captain Dawson)", "මේජර් ස්කිනර්", "ජෝන් මැකඩම්", "ජෝර්ජ් ස්ටීවන්සන්", "කඩුගන්නාව මුදුනේ පිහිටුවා ඇති සුදු පැහැති ඩෝසන් කුලුන (Dawson Tower) ඉදිකර ඇත්තේ මෙම මහා මාර්ගය තැනූ ඩෝසන් සිහිවීම පිණිසයි."),
    q(T, "කඩුගන්නාවේදී මහා ගල විද උමඟක් තනමින් 'ගල විද පාරක් තනන තුරු උඩරට යටත් කළ නොහැක' යන සිංහල අනාවැකිය සැබෑ කළ ආණ්ඩුකාරවරයා කවුද?", "ශ්‍රීමත් එඩ්වඩ් බාන්ස් (Sir Edward Barnes)", "රොබට් බ්‍රවුන්රිග්", "තෝමස් මේට්ලන්ඩ්", "ෆ්‍රෙඩ්රික් නෝර්ත්", "බාන්ස් ආණ්ඩුකාරවරයාගේ මහා මාර්ග සංවර්ධනය යටතේ කොළඹ-මහනුවර මාර්ගය නිමවා උඩරට හමුදාමය වශයෙන් සම්පූර්ණයෙන්ම සම්බන්ධ කරන ලදී."),
    q(T, "1867 දී ශ්‍රී ලංකාවේ ප්‍රථම දුම්රිය මාර්ගය විවෘත කරන ලද්දේ කුමන නගර දෙක අතරද?", "කොළඹ සහ අඹේපුස්ස අතර (පසුව මහනුවර දක්වා)", "කොළඹ සහ ගාල්ල අතර", "මහනුවර සහ බදුල්ල අතර", "කොළඹ සහ යාපනය අතර", "කඳුකරයේ කෝපි අස්වැන්න ඉක්මනින් කොළඹ වරායට ප්‍රවාහනය කිරීම සඳහා 1864 දී අඹේපුස්සටත් 1867 දී මහනුවරටත් දුම්රිය මාර්ගය විවෘත කරන ලදී."),
    q(T, "ශ්‍රී ලංකාවේ මහා මාර්ග හා පාලම් පද්ධතිය දීර්ඝ කාලයක් තිස්සේ ඉදිකරමින් 'මහා මාර්ග තැනීමේ පියා' ලෙස සැලකෙන බ්‍රිතාන්‍ය නිලධාරියා කවුද?", "මේජර් තෝමස් ස්කිනර් (Major Thomas Skinner)", "කැප්ටන් ඩෝසන්", "එඩ්වඩ් බාන්ස්", "ජෝන් ඩොයිලි", "වසර 50 කට ආසන්න කාලයක් පොදු වැඩ දෙපාර්තමේන්තුවේ සේවය කරමින් ලංකාව පුරා මහා මාර්ග ජාලයක් බිහිකිරීමට ස්කිනර් මූලික විය."),
